def normalize_study_evaluation_protocol(value: Any) -> dict[str, Any] | None:
    """Return the bounded, condition-blind protocol shared by a paired trial.

    The object is rebuilt from an allowlist so A/B labels, hidden condition
    names, developer summaries, conversations and virtual-user narratives
    cannot reach the release evaluator through this channel.
    """

    if value in (None, "", {}):
        return None
    if isinstance(value, str):
        if len(value) > 24_000:
            raise WorkflowError("study evaluation protocol is too large")
        try:
            value = json.loads(value)
        except json.JSONDecodeError as exc:
            raise WorkflowError("study evaluation protocol must be valid JSON") from exc
    if not isinstance(value, dict):
        raise WorkflowError("study evaluation protocol must be an object")

    version = str(value.get("version") or "").strip()
    if version != STUDY_EVALUATION_PROTOCOL_VERSION:
        raise WorkflowError("unsupported study evaluation protocol version")
    if value.get("blinded") is not True:
        raise WorkflowError("study release evaluation must be blinded")

    evaluator = value.get("evaluator")
    if not isinstance(evaluator, dict):
        raise WorkflowError("study evaluator contract is missing")
    model = str(evaluator.get("model") or "").strip()
    prompt_id = str(evaluator.get("prompt_id") or "").strip()
    if not model or len(model) > 120 or not re.fullmatch(r"[A-Za-z0-9._:/-]+", model):
        raise WorkflowError("study evaluator model is invalid")
    if prompt_id != STUDY_EVALUATOR_PROMPT_ID:
        raise WorkflowError("study evaluator prompt is not the frozen blinded prompt")
    try:
        temperature = float(evaluator.get("temperature"))
        max_attempts = int(evaluator.get("max_attempts"))
    except (TypeError, ValueError) as exc:
        raise WorkflowError("study evaluator parameters are invalid") from exc
    if temperature != STUDY_EVALUATOR_DEFAULT_TEMPERATURE:
        raise WorkflowError("study evaluator temperature must be 0")
    if max_attempts < 1 or max_attempts > 5:
        raise WorkflowError("study evaluator max_attempts must be between 1 and 5")

    shared_cuj = value.get("shared_cuj")
    if not isinstance(shared_cuj, dict):
        raise WorkflowError("shared CUJ is missing")
    cuj_id = str(shared_cuj.get("id") or "").strip()
    actor = str(shared_cuj.get("actor") or "").strip()
    goal = str(shared_cuj.get("goal") or "").strip()
    if not cuj_id or len(cuj_id) > 80 or not re.fullmatch(r"[A-Za-z0-9._-]+", cuj_id):
        raise WorkflowError("shared CUJ id is invalid")
    if not actor or len(actor) > 300 or not goal or len(goal) > 2_000:
        raise WorkflowError("shared CUJ actor or goal is invalid")
    steps: list[dict[str, str]] = []
    seen_step_ids: set[str] = set()
    for raw in shared_cuj.get("steps") or []:
        if not isinstance(raw, dict):
            raise WorkflowError("shared CUJ steps must be objects")
        step_id = str(raw.get("id") or "").strip()
        action = str(raw.get("action") or "").strip()
        if (
            not step_id
            or step_id in seen_step_ids
            or len(step_id) > 80
            or not re.fullmatch(r"[A-Za-z0-9._-]+", step_id)
            or not action
            or len(action) > 1_000
        ):
            raise WorkflowError("shared CUJ contains an invalid step")
        seen_step_ids.add(step_id)
        steps.append({"id": step_id, "action": action})
    if not steps or len(steps) > STUDY_SHARED_CUJ_MAX_STEPS:
        raise WorkflowError("shared CUJ must contain a bounded non-empty step list")

    regression = value.get("regression_policy")
    if not isinstance(regression, dict):
        raise WorkflowError("study regression policy is missing")
    regression_policy_id = str(regression.get("id") or "").strip()
    if regression_policy_id != "declared-tests-plus-frozen-requirements-v1":
        raise WorkflowError("study regression policy is invalid")

    return {
        "version": STUDY_EVALUATION_PROTOCOL_VERSION,
        "blinded": True,
        "evaluator": {
            "model": model,
            "temperature": STUDY_EVALUATOR_DEFAULT_TEMPERATURE,
            "max_attempts": max_attempts,
            "prompt_id": STUDY_EVALUATOR_PROMPT_ID,
        },
        "regression_policy": {
            "id": regression_policy_id,
            "require_project_declared_tests": True,
            "require_frozen_requirement_checks": True,
        },
        "shared_cuj": {
            "id": cuj_id,
            "actor": actor,
            "goal": goal,
            "steps": steps,
        },
    }


def study_evaluator_contract(state: dict[str, Any]) -> dict[str, Any]:
    protocol = normalize_study_evaluation_protocol(state.get("study_evaluation_protocol"))
    if protocol is not None:
        return dict(protocol["evaluator"])
    return {
        "model": str(state.get("model") or os.environ.get("WF_MODEL") or "provider-default"),
        "temperature": STUDY_EVALUATOR_DEFAULT_TEMPERATURE,
        "max_attempts": STUDY_EVALUATOR_DEFAULT_MAX_ATTEMPTS,
        "prompt_id": STUDY_EVALUATOR_PROMPT_ID,
    }


def model_for_role(state: dict[str, Any], role: str) -> str:
    """Resolve a role-specific model without mutating the global worker model."""

    normalized_role = (
        "owner_proxy"
        if str(role) == "owner_feedback_precheck"
        else "reviewer"
        if str(role) == "reviewer"
        else str(role)
    )
    if normalized_role == "reviewer":
        protocol = normalize_study_evaluation_protocol(state.get("study_evaluation_protocol"))
        if protocol is not None:
            return str(protocol["evaluator"].get("model") or "")
    overrides = state.get("role_model_overrides")
    if isinstance(overrides, dict) and str(overrides.get(normalized_role) or ""):
        return str(overrides[normalized_role])
    return str(state.get("model") or "")


def study_shared_cuj_steps(state: dict[str, Any]) -> list[dict[str, str]]:
    protocol = normalize_study_evaluation_protocol(state.get("study_evaluation_protocol"))
    if protocol is None:
        return []
    return [dict(step) for step in protocol["shared_cuj"]["steps"]]


def hidden_process_kwargs() -> dict[str, Any]:
    """Keep background coding-agent console programs invisible on Windows."""
    if os.name != "nt":
        return {}
    startup = subprocess.STARTUPINFO()
    startup.dwFlags |= subprocess.STARTF_USESHOWWINDOW
    startup.wShowWindow = subprocess.SW_HIDE
    return {"creationflags": subprocess.CREATE_NO_WINDOW, "startupinfo": startup}


def isolated_process_kwargs() -> dict[str, Any]:
    """Launch a CLI in a process group that can be torn down as one unit."""
    kwargs = hidden_process_kwargs()
    if os.name == "nt":
        kwargs["creationflags"] = int(kwargs.get("creationflags") or 0) | int(
            subprocess.CREATE_NEW_PROCESS_GROUP
        )
    else:
        kwargs["start_new_session"] = True
    return kwargs


def attach_windows_process_job(proc: subprocess.Popen[Any]) -> None:
    """Put a Windows child in a Job Object for reliable tree termination."""
    if os.name != "nt":
        return
    try:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
        kernel32.CreateJobObjectW.restype = wintypes.HANDLE
        kernel32.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
        kernel32.AssignProcessToJobObject.restype = wintypes.BOOL
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        kernel32.CloseHandle.restype = wintypes.BOOL
        handle = kernel32.CreateJobObjectW(None, None)
        if not handle:
            return
        if not kernel32.AssignProcessToJobObject(handle, int(proc._handle)):
            kernel32.CloseHandle(handle)
            return
        setattr(proc, "_workflow_job_handle", int(handle))
    except Exception:
        # Older/constrained Windows hosts can reject nested jobs.  The native
        # process-tree walk and taskkill fallback below still run on timeout.
        return


def close_windows_process_job(proc: subprocess.Popen[Any]) -> None:
    if os.name != "nt":
        return
    handle = int(getattr(proc, "_workflow_job_handle", 0) or 0)
    if not handle:
        return
    with contextlib.suppress(Exception):
        import ctypes

        ctypes.windll.kernel32.CloseHandle(handle)
    setattr(proc, "_workflow_job_handle", 0)


def terminate_windows_process_job(proc: subprocess.Popen[Any]) -> bool:
    if os.name != "nt":
        return False
    handle = int(getattr(proc, "_workflow_job_handle", 0) or 0)
    if not handle:
        return False
    try:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.TerminateJobObject.argtypes = [wintypes.HANDLE, wintypes.UINT]
        kernel32.TerminateJobObject.restype = wintypes.BOOL
        return bool(kernel32.TerminateJobObject(handle, 1))
    except Exception:
        return False


def terminate_windows_process_descendants(root_pid: int) -> None:
    """Best-effort Toolhelp fallback when taskkill or nested jobs are denied."""
    if os.name != "nt":
        return
    try:
        import ctypes
        from ctypes import wintypes

        class ProcessEntry32W(ctypes.Structure):
            _fields_ = [
                ("dwSize", wintypes.DWORD),
                ("cntUsage", wintypes.DWORD),
                ("th32ProcessID", wintypes.DWORD),
                ("th32DefaultHeapID", ctypes.c_size_t),
                ("th32ModuleID", wintypes.DWORD),
                ("cntThreads", wintypes.DWORD),
                ("th32ParentProcessID", wintypes.DWORD),
                ("pcPriClassBase", wintypes.LONG),
                ("dwFlags", wintypes.DWORD),
                ("szExeFile", wintypes.WCHAR * 260),
            ]

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateToolhelp32Snapshot.argtypes = [wintypes.DWORD, wintypes.DWORD]
        kernel32.CreateToolhelp32Snapshot.restype = wintypes.HANDLE
        kernel32.Process32FirstW.argtypes = [wintypes.HANDLE, ctypes.POINTER(ProcessEntry32W)]
        kernel32.Process32FirstW.restype = wintypes.BOOL
        kernel32.Process32NextW.argtypes = [wintypes.HANDLE, ctypes.POINTER(ProcessEntry32W)]
        kernel32.Process32NextW.restype = wintypes.BOOL
        kernel32.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
        kernel32.OpenProcess.restype = wintypes.HANDLE
        kernel32.TerminateProcess.argtypes = [wintypes.HANDLE, wintypes.UINT]
        kernel32.TerminateProcess.restype = wintypes.BOOL
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        kernel32.CloseHandle.restype = wintypes.BOOL
        snapshot = kernel32.CreateToolhelp32Snapshot(0x00000002, 0)
        invalid_handle = ctypes.c_void_p(-1).value
        if not snapshot or int(snapshot) == invalid_handle:
            return
        try:
            entry = ProcessEntry32W()
            entry.dwSize = ctypes.sizeof(entry)
            parent_by_pid: dict[int, int] = {}
            if kernel32.Process32FirstW(snapshot, ctypes.byref(entry)):
                while True:
                    parent_by_pid[int(entry.th32ProcessID)] = int(entry.th32ParentProcessID)
                    if not kernel32.Process32NextW(snapshot, ctypes.byref(entry)):
                        break
        finally:
            kernel32.CloseHandle(snapshot)
        descendants: set[int] = set()
        changed = True
        while changed:
            changed = False
            for pid, parent_pid in parent_by_pid.items():
                if pid in descendants or pid == root_pid:
                    continue
                if parent_pid == root_pid or parent_pid in descendants:
                    descendants.add(pid)
                    changed = True
        for pid in reversed(list(descendants)):
            handle = kernel32.OpenProcess(0x0001, False, pid)
            if not handle:
                continue
            try:
                kernel32.TerminateProcess(handle, 1)
            finally:
                kernel32.CloseHandle(handle)
    except Exception:
        return


def resolve_cli_executable(configured: str, fallback: str) -> str:
    """Resolve an explicit CLI setting or a command name without trusting the cwd."""
    wanted = str(configured or "").strip().strip('"')
    name = wanted or fallback
    if not name:
        return ""
    # Packaged Windows applications can publish an executable into PATH before
    # its AppContainer ACL is ready for ordinary background processes.  The
    # user-level npm shim is both stable across Store updates and directly
    # runnable through ``cmd.exe``, so prefer it for implicit CLI discovery.
    if os.name == "nt" and not wanted:
        appdata = str(os.environ.get("APPDATA") or "").strip()
        if appdata:
            npm_dir = Path(appdata) / "npm"
            for suffix in (".cmd", ".exe", ".bat", ".ps1"):
                candidate = npm_dir / f"{fallback}{suffix}"
                try:
                    if candidate.is_file():
                        return str(candidate.resolve())
                except (OSError, RuntimeError, ValueError):
                    continue
    try:
        found = shutil.which(name)
    except (OSError, ValueError):
        found = None
    if found:
        try:
            return str(Path(found).resolve())
        except (OSError, RuntimeError, ValueError):
            return str(found)
    if wanted:
        try:
            candidate = Path(wanted).expanduser()
            if candidate.is_file():
                return str(candidate.resolve())
        except (OSError, RuntimeError, ValueError):
            pass
    return ""


def cli_command_prefix(executable: str) -> list[str]:
    """Return a directly runnable argv prefix for native, npm shim, or PS1 CLIs."""
    suffix = Path(executable).suffix.casefold()
    if os.name == "nt" and suffix in {".cmd", ".bat"}:
        try:
            located_comspec = shutil.which("cmd.exe")
        except (OSError, ValueError):
            located_comspec = None
        comspec = os.environ.get("COMSPEC") or located_comspec or "cmd.exe"
        return [comspec, "/d", "/c", executable]
    if os.name == "nt" and suffix == ".ps1":
        try:
            powershell = shutil.which("powershell.exe") or shutil.which("pwsh.exe")
        except (OSError, ValueError):
            powershell = None
        powershell = powershell or "powershell.exe"
        return [
            powershell,
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            executable,
        ]
    return [executable]


def process_output_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    return str(value)


def combine_process_output(partial: Any, final: Any) -> str:
    first, second = process_output_text(partial), process_output_text(final)
    if not first or second.startswith(first):
        return second or first
    if first.startswith(second):
        return first
    return first + second


def terminate_process_tree(
    proc: subprocess.Popen[Any],
    *,
    isolated_session: bool = False,
) -> None:
    """Best-effort termination, including the child behind a Windows npm shim."""
    if os.name == "nt":
        terminated_job = terminate_windows_process_job(proc)
        if not terminated_job:
            terminate_windows_process_descendants(proc.pid)
        # A successfully terminated Windows Job already killed the complete
        # descendant tree. Running taskkill again adds several seconds to every
        # timeout and can make the worker appear stuck after its deadline.
        if not terminated_job and (isolated_session or proc.poll() is None):
            try:
                subprocess.run(
                    ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                    capture_output=True,
                    timeout=10,
                    check=False,
                    **hidden_process_kwargs(),
                )
            except (OSError, subprocess.TimeoutExpired):
                pass
        if proc.poll() is None:
            with contextlib.suppress(OSError):
                proc.kill()
        return

    # ``isolated_process_kwargs`` makes the subprocess the leader of a new
    # POSIX session.  Kill the whole group so grandchildren holding inherited
    # stdout/stderr descriptors cannot outlive a timed-out Claude invocation.
    process_group: int | None = proc.pid if isolated_session else None
    if process_group is None and proc.poll() is None:
        with contextlib.suppress(OSError):
            candidate = os.getpgid(proc.pid)
            if candidate == proc.pid:
                process_group = candidate
    if process_group is not None:
        with contextlib.suppress(OSError):
            os.killpg(process_group, signal.SIGTERM)
    if process_group is not None:
        with contextlib.suppress(subprocess.TimeoutExpired):
            proc.wait(timeout=0.5)
        # A descendant may ignore SIGTERM after the direct child exits, so
        # always follow with SIGKILL for the now-dedicated process group.
        with contextlib.suppress(OSError):
            os.killpg(process_group, signal.SIGKILL)
    if proc.poll() is None:
        with contextlib.suppress(OSError):
            proc.kill()


def run_coding_process(
    command: list[str],
    *,
    cwd: str,
    input_text: str,
    timeout: int,
    env: dict[str, str],
    on_stdout_line: Any = None,
) -> subprocess.CompletedProcess[str]:
    """Run a coding CLI and retain partial output when a timed-out tree is killed."""
    proc = subprocess.Popen(
        command,
        cwd=cwd,
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        env=env,
        **hidden_process_kwargs(),
    )
    if callable(on_stdout_line):
        stdout_chunks: list[str] = []
        stderr_chunks: list[str] = []
        callback_errors: list[BaseException] = []

        def read_stdout() -> None:
            if not proc.stdout:
                return
            for line in proc.stdout:
                stdout_chunks.append(line)
                if callback_errors:
                    continue
                try:
                    on_stdout_line(line)
                except BaseException as exc:  # keep draining both process pipes
                    callback_errors.append(exc)

        def read_stderr() -> None:
            if not proc.stderr:
                return
            stderr_chunks.extend(proc.stderr)

        stdout_thread = threading.Thread(target=read_stdout, daemon=True)
        stderr_thread = threading.Thread(target=read_stderr, daemon=True)
        stdout_thread.start()
        stderr_thread.start()
        try:
            if proc.stdin:
                proc.stdin.write(input_text)
                proc.stdin.close()
            proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired as exc:
            terminate_process_tree(proc)
            with contextlib.suppress(subprocess.TimeoutExpired):
                proc.wait(timeout=5)
            stdout_thread.join(timeout=2)
            stderr_thread.join(timeout=2)
            raise subprocess.TimeoutExpired(
                command,
                timeout,
                output="".join(stdout_chunks),
                stderr="".join(stderr_chunks),
            ) from exc
        except BaseException:
            terminate_process_tree(proc)
            raise
        finally:
            stdout_thread.join(timeout=2)
            stderr_thread.join(timeout=2)
            for stream in (proc.stdin, proc.stdout, proc.stderr):
                if stream:
                    with contextlib.suppress(OSError):
                        stream.close()
        if callback_errors:
            raise callback_errors[0]
        return subprocess.CompletedProcess(
            command,
            proc.returncode if proc.returncode is not None else 1,
            "".join(stdout_chunks),
            "".join(stderr_chunks),
        )
    try:
        stdout, stderr = proc.communicate(input_text, timeout=timeout)
    except subprocess.TimeoutExpired as exc:
        terminate_process_tree(proc)
        try:
            final_stdout, final_stderr = proc.communicate(timeout=5)
        except subprocess.TimeoutExpired:
            with contextlib.suppress(OSError):
                proc.kill()
            final_stdout, final_stderr = proc.communicate()
        raise subprocess.TimeoutExpired(
            command,
            timeout,
            output=combine_process_output(exc.stdout, final_stdout),
            stderr=combine_process_output(exc.stderr, final_stderr),
        ) from exc
    except BaseException:
        terminate_process_tree(proc)
        raise
    return subprocess.CompletedProcess(command, proc.returncode, stdout, stderr)


