def obj(properties: dict[str, Any], required: list[str]) -> dict[str, Any]:
    return {"type": "object", "properties": properties, "required": required, "additionalProperties": False}


def codex_strict_output_schema(schema: dict[str, Any]) -> dict[str, Any]:
    """Return a Codex-compatible strict schema without mutating the source.

    Codex structured output requires every object property to appear in
    ``required``.  Product schemas still use omitted properties to express
    optional values, so preserve that meaning by making those properties
    nullable in the provider-facing copy.
    """

    def allows_null(value: Any) -> bool:
        if not isinstance(value, dict):
            return False
        value_type = value.get("type")
        if value_type == "null" or (isinstance(value_type, list) and "null" in value_type):
            return True
        return any(
            allows_null(option)
            for keyword in ("anyOf", "oneOf")
            for option in (value.get(keyword) if isinstance(value.get(keyword), list) else [])
        )

    def normalize(value: Any) -> Any:
        if isinstance(value, list):
            return [normalize(item) for item in value]
        if not isinstance(value, dict):
            return value

        normalized = {
            key: normalize(item)
            for key, item in value.items()
            if key not in {"properties", "required"}
        }
        properties = value.get("properties")
        if not isinstance(properties, dict):
            if "required" in value:
                normalized["required"] = normalize(value["required"])
            return normalized

        originally_required = {
            str(item)
            for item in value.get("required", [])
            if isinstance(item, str)
        }
        normalized_properties: dict[str, Any] = {}
        for name, child in properties.items():
            normalized_child = normalize(child)
            if name not in originally_required and not allows_null(normalized_child):
                normalized_child = {
                    "anyOf": [
                        normalized_child,
                        {"type": "null"},
                    ]
                }
            normalized_properties[name] = normalized_child

        normalized["properties"] = normalized_properties
        normalized["required"] = list(properties)
        normalized["additionalProperties"] = False
        return normalized

    return normalize(schema)


