def is_agnes_qualification_state(state: dict[str, Any]) -> bool:
    intent = str(state.get("intent") or "")
    workspace = str(state.get("workspace") or "").replace("\\", "/")
    return (
        os.environ.get("WF_AGNES_COMPAT") == "1"
        and (
            "Agnes资格测试-" in intent
            or "/.applooper-trials/" in workspace
            or "/applooper-trials/" in workspace
        )
    )


def should_expand_study_persona_cohort(state: dict[str, Any]) -> bool:
    """Expand fictional virtual users for study treatment and trial workspaces."""

    if is_agnes_qualification_state(state):
        return True
    condition = str(state.get("study_condition") or "").strip()
    if condition and condition != STUDY_BASELINE_CONDITION:
        return True
    workspace = str(state.get("workspace") or "").replace("\\", "/")
    return "/applooper-trials/" in workspace or "/.applooper-trials/" in workspace


def qualification_planning_tools(state: dict[str, Any]) -> list[str] | None:
    """Keep blank Agnes qualification planning free of filesystem exploration."""

    return ["StructuredOutput"] if is_agnes_qualification_state(state) else None


def plan_schema_for_state(state: dict[str, Any]) -> dict[str, Any]:
    """Use stricter, machine-checkable bounds only for Agnes qualification trials."""

    if not is_agnes_qualification_state(state):
        return PLAN_SCHEMA
    schema = json.loads(json.dumps(PLAN_SCHEMA))
    properties = schema["properties"]
    properties["personas"]["minItems"] = 1
    properties["personas"]["maxItems"] = 1
    properties["required_segments"]["minItems"] = 1
    properties["required_segments"]["maxItems"] = 1
    properties["tasks"]["minItems"] = 2
    properties["tasks"]["maxItems"] = 2
    return schema


def agnes_cli_output_schema(schema: dict[str, Any]) -> dict[str, Any]:
    """Let the CLI accept deterministic Agnes transport variants.

    The returned value is used only by Claude CLI's StructuredOutput tool. The
    original strict schema is still used after provider normalization, so a
    prose string or malformed JSON remains a hard failure. Unknown task status
    labels are handled conservatively only for experience task rows: the host
    records the evidence as BLOCKED and never upgrades an unknown label to a
    pass. Other enum fields remain strict.
    """

    tolerant = json.loads(json.dumps(schema))

    def relax_experience_status(node: Any) -> None:
        if isinstance(node, dict):
            enum_values = node.get("enum")
            if (
                node.get("type") == "string"
                and isinstance(enum_values, list)
                and set(enum_values) == {"PASS", "FAIL", "BLOCKED"}
            ):
                # Agnes commonly emits semantically exact aliases such as
                # completed/succeeded/skipped. Let the transport deliver them;
                # normalize_provider_schema_value maps the finite alias set and
                # the original schema below remains the acceptance boundary.
                node.pop("enum", None)
            for child in node.values():
                relax_experience_status(child)
        elif isinstance(node, list):
            for child in node:
                relax_experience_status(child)

    relax_experience_status(tolerant)
    properties = tolerant.get("properties")
    if not isinstance(properties, dict):
        return tolerant
    guardrails = properties.get("guardrails")
    guardrail_items = (
        guardrails.get("items")
        if isinstance(guardrails, dict) and isinstance(guardrails.get("items"), dict)
        else {}
    )
    guardrail_properties = (
        guardrail_items.get("properties")
        if isinstance(guardrail_items.get("properties"), dict)
        else {}
    )
    if (
        isinstance(guardrails, dict)
        and guardrails.get("type") == "array"
        and {"text", "acceptance", "source_quote"}.issubset(guardrail_properties)
    ):
        properties["guardrails"] = {
            "anyOf": [
                guardrails,
                {"type": "string"},
            ]
        }
    return tolerant
