class WorkflowError(RuntimeError):
    pass


class WorkflowStopRequested(WorkflowError):
    """Raised when an active coding-agent call observes the run stop marker."""


class FatalWorkflowError(WorkflowError):
    """State/safety failures that must not be retried automatically."""


# --- Externally-visible egress guard (architectural invariant, not a prompt) ---
#
# No agent role may produce an external side effect from its shell: publishing
# code, provisioning remotes, deploying, ingesting telemetry (埋点), mass
# messaging (群发), or paid actions. The ONLY sanctioned path to an external
# effect is the human-gated release action in the web layer (server-verified
# checklist + typed attestation). This guard enforces that in code by hard-
# failing the iteration when such a command is observed in the agent's real
# tool-use stream, independent of what the prompt says. Credentials and git
# remotes are never provisioned to agents, so a hard-failed attempt also cannot
# complete. Loopback HTTP (local app testing) and read-only GET fetches remain
# allowed.
EGRESS_COMMAND_PATTERNS = (
    r"\bgit\s+push\b",
    r"\bgit\s+remote\s+(?:add|set-url|set-branches)\b",
    r"\bgh\s+(?:repo|release|pr|api|workflow|secret|gist|auth)\b",
    r"\bglab\s+[a-z]+",
    r"\b(?:npm|yarn|pnpm)\s+publish\b",
    r"\btwine\s+upload\b",
    r"\bpython\s+-m\s+twine\b",
    r"\bgem\s+push\b",
    r"\bcargo\s+publish\b",
    r"\bdocker\s+push\b",
    r"\b(?:vercel|netlify|firebase|heroku|flyctl|serverless|wrangler)\b[^\n]*\b(?:deploy|publish|release)\b",
    r"\bfly\s+deploy\b",
    r"\b(?:eas|expo)\s+(?:publish|submit|deploy)\b",
    r"\bgcloud\s+(?:app|run|functions)\s+deploy\b",
    r"\baws\s+(?:deploy\b|s3\s+(?:cp|sync|mv|rm|rb)\b|s3api\s+(?:put|delete))",
    r"\baz\s+webapp\b",
    r"\bkubectl\s+apply\b",
    r"\bsam\s+deploy\b",
    r"\b(?:sendmail|mailx|msmtp|swaks|mutt)\b",
    r"\b(?:scp|rsync)\s+[^\n]+:[^\n]",
    r"\bssh\s+[A-Za-z0-9._%-]+@",
)
_EGRESS_RE = re.compile("|".join(EGRESS_COMMAND_PATTERNS), re.IGNORECASE)
_EGRESS_HTTP_TOOL_RE = re.compile(r"\b(?:curl|wget|Invoke-WebRequest|iwr)\b", re.IGNORECASE)
_EGRESS_HTTP_WRITE_RE = re.compile(
    r"(?:-X\s*(?:POST|PUT|DELETE|PATCH)|--request\s*(?:POST|PUT|DELETE|PATCH)"
    r"|--data(?:-binary|-raw|-urlencode)?\b|(?<!\w)-d\b|--form\b|(?<!\w)-F\b"
    r"|--upload-file\b|(?<!\w)-T\b|-Method\s*(?:Post|Put|Delete|Patch))",
    re.IGNORECASE,
)
_LOOPBACK_URL_RE = re.compile(
    r"https?://(?:localhost|127\.0\.0\.1|\[::1\]|0\.0\.0\.0)(?::\d+)?", re.IGNORECASE
)
_ANY_URL_RE = re.compile(r"https?://[^\s'\"\\]+", re.IGNORECASE)

# Roles whose shell must never egress. surface_prep is excluded because its
# sanctioned job includes user-confirmed dependency/runtime installation.
EGRESS_GUARDED_ROLES = frozenset({"developer", "orchestrator", "operations"})


def detect_unauthorized_egress(tool_uses: Any) -> str | None:
    """Return the offending command string if an external side effect was
    attempted in the observed tool-use stream, else None."""
    for entry in tool_uses or []:
        text = str(entry)
        match = _EGRESS_RE.search(text)
        if match:
            return match.group(0).strip()[:200]
        if _EGRESS_HTTP_TOOL_RE.search(text) and _EGRESS_HTTP_WRITE_RE.search(text):
            urls = _ANY_URL_RE.findall(text)
            external = [url for url in urls if not _LOOPBACK_URL_RE.match(url)]
            if external:
                tool = _EGRESS_HTTP_TOOL_RE.search(text)
                return f"{tool.group(0)} -> {external[0]}"[:200]
    return None


def enforce_egress_policy(role: str, tool_uses: Any) -> None:
    """Fail the iteration if a guarded role attempted an external side effect."""
    base_role = str(role or "").split(":", 1)[0]
    if base_role not in EGRESS_GUARDED_ROLES:
        return
    offending = detect_unauthorized_egress(tool_uses)
    if offending:
        raise FatalWorkflowError(
            f"{role} 试图执行未授权的对外操作（发布/建远端/部署/埋点/群发/付费只能经发布门禁由人确认）：{offending}"
        )


def write_egress_hook_settings(
    io_dir: Path,
    workspace: Path | None = None,
    *,
    enforce_egress: bool = True,
    enforce_read_only: bool = False,
    protect_preview: bool = False,
) -> tuple[Path, Path]:
    """Emit a Claude Code settings file whose PreToolUse hook DENIES external
    side-effect Bash commands before they execute (pre-execution interception).

    The hook mirrors detect_unauthorized_egress by reusing the very same
    compiled patterns, so there is one source of truth; enforce_egress_policy
    stays as the post-hoc backstop for CLI builds that ignore the hook. Returns
    (settings_path, guard_path) so the caller can clean both up."""

    workspace_path = workspace.expanduser().resolve(strict=False) if workspace is not None else None
    project_root = ""
    if workspace_path is not None and ".applooper-trials" in workspace_path.parts:
        trial_index = workspace_path.parts.index(".applooper-trials")
        project_root = str(Path(*workspace_path.parts[:trial_index]))
        if workspace_path.anchor and not project_root.startswith(workspace_path.anchor):
            project_root = str(Path(workspace_path.anchor) / project_root)
    guard_path = io_dir / f"egress-guard-{uuid.uuid4().hex}.py"
    guard = (
        "import json,os,re,sys\n"
        f"_RE=re.compile({_EGRESS_RE.pattern!r},re.I)\n"
        f"_TOOL=re.compile({_EGRESS_HTTP_TOOL_RE.pattern!r},re.I)\n"
        f"_WRITE=re.compile({_EGRESS_HTTP_WRITE_RE.pattern!r},re.I)\n"
        f"_LOOP=re.compile({_LOOPBACK_URL_RE.pattern!r},re.I)\n"
        f"_URL=re.compile({_ANY_URL_RE.pattern!r},re.I)\n"
        f"_WORKSPACE={str(workspace_path) if workspace_path is not None else ''!r}\n"
        f"_PROJECT_ROOT={project_root!r}\n"
        f"_ENFORCE_EGRESS={bool(enforce_egress)!r}\n"
        f"_READ_ONLY={bool(enforce_read_only)!r}\n"
        f"_PROTECT_PREVIEW={bool(protect_preview)!r}\n"
        "def off(c):\n"
        "    if not _ENFORCE_EGRESS:return None\n"
        "    m=_RE.search(c)\n"
        "    if m:return m.group(0).strip()[:200]\n"
        "    if _TOOL.search(c) and _WRITE.search(c):\n"
        "        e=[u for u in _URL.findall(c) if not _LOOP.match(u)]\n"
        "        if e:return e[0][:200]\n"
        "    return None\n"
        "def inside(p):\n"
        "    if not _WORKSPACE:return True\n"
        "    if not os.path.isabs(p):p=os.path.join(_WORKSPACE,p)\n"
        "    p=os.path.realpath(p)\n"
        "    return p==_WORKSPACE or p.startswith(_WORKSPACE+os.sep)\n"
        "def workspace_off(d):\n"
        "    if not _WORKSPACE:return None\n"
        "    tool=str(d.get('tool_name') or '')\n"
        "    inp=d.get('tool_input') or {}\n"
        "    fields={'Read':('file_path','path'),'Glob':('path',),'Grep':('path',),"
        "'Edit':('file_path','path'),'Write':('file_path','path'),"
        "'NotebookEdit':('notebook_path','file_path','path')}\n"
        "    for field in fields.get(tool,()):\n"
        "        value=str(inp.get(field) or '').strip()\n"
        "        if value and not inside(value):return tool+' '+field+' outside trial workspace'\n"
        "    if tool=='Bash':\n"
        "        command=str(inp.get('command') or '')\n"
        "        if _PROTECT_PREVIEW and re.search(r'(^|[\\s;&|])(?:pkill|killall|kill)(?:\\s|$)',command,re.I):\n"
        "            return 'Preview server must remain running through workflow handoff'\n"
        "        for target in re.findall(r'(?<!>)>>?(?!>)\\s*([^\\s;&|]+)',command):\n"
        "            candidate=target.strip(\"'\\\"()[]{}:, \")\n"
        "            if candidate in ('/dev/null','&1','&2'):continue\n"
        "            if '$' in candidate or '`' in candidate:\n"
        "                return 'Bash redirect target must be an explicit path inside trial workspace'\n"
        "            if candidate and not inside(candidate):\n"
        "                return 'Bash output redirection outside trial workspace'\n"
        "        if _READ_ONLY:\n"
        "            redirect_check=re.sub(r'(?<!\\S)(?:[0-9]+)?>>?\\s*/dev/null\\b','',command)\n"
        "            if re.search(r'(^|[^>])>>?(?!>)',redirect_check):\n"
        "                return 'Bash output redirection is forbidden for a read-only role'\n"
        "            if re.search(r'(^|[\\s;&|])(?:tee|touch|mkdir|rm|rmdir|mv|cp|install|truncate)(?:\\s|$)',command,re.I):\n"
        "                return 'Bash filesystem mutation is forbidden for a read-only role'\n"
        "            if re.search(r'\\b(?:sed\\s+-[^\\n]*i|perl\\s+-[^\\n]*i|git\\s+(?:add|commit|checkout|switch|reset|clean|merge|rebase|cherry-pick))\\b',command,re.I):\n"
        "                return 'Bash mutation command is forbidden for a read-only role'\n"
        "        if re.search(r'(^|[\\s;&|()])\\.\\.(?:/|\\\\|$)',command):\n"
        "            return 'Bash parent traversal outside trial workspace'\n"
        "        if _PROJECT_ROOT and _PROJECT_ROOT in command.replace(_WORKSPACE,''):\n"
        "            return 'Bash path outside trial workspace'\n"
        "        for token in re.findall(r'(?<![A-Za-z0-9_.-])/[^^\\s;|&<>]+',command):\n"
        "            candidate=token.strip(\"'\\\"()[]{}:, \")\n"
        "            if _PROJECT_ROOT and (candidate==_PROJECT_ROOT or candidate.startswith(_PROJECT_ROOT+os.sep)):\n"
        "                if not inside(candidate):return 'Bash path outside trial workspace'\n"
        "    return None\n"
        "try:\n"
        "    d=json.load(sys.stdin)\n"
        "except Exception:\n"
        "    sys.exit(0)\n"
        "tool=str(d.get('tool_name') or '')\n"
        "c=str((d.get('tool_input') or {}).get('command') or '')\n"
        "h=workspace_off(d) or (off(c) if tool=='Bash' else None)\n"
        "if h:\n"
        "    sys.stderr.write('AppLooper blocked a command outside this trial workspace or an "
        "external side effect. Publishing, deployment and cross-trial file access must pass the "
        "appropriate boundary. Offending: '+h)\n"
        "    sys.exit(2)\n"
        "sys.exit(0)\n"
    )
    guard_path.write_text(guard, encoding="utf-8")
    settings_path = io_dir / f"egress-settings-{uuid.uuid4().hex}.json"
    hook_command = f'"{sys.executable}" "{guard_path}"'
    matchers = ["Bash"]
    if workspace_path is not None:
        matchers.extend(["Read", "Glob", "Grep", "Edit", "Write", "NotebookEdit"])
    settings_path.write_text(
        json.dumps(
            {
                "hooks": {
                    "PreToolUse": [
                        {
                            "matcher": matcher,
                            "hooks": [{"type": "command", "command": hook_command}],
                        }
                        for matcher in matchers
                    ]
                }
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )
    return settings_path, guard_path


def project_repository_skill_text() -> str:
    """Load the bundled repository Skill after a small fail-closed validation."""

    path = PROJECT_REPOSITORY_SKILL_PATH
    try:
        if not path.is_file() or path.stat().st_size > 64_000:
            raise OSError("missing or oversized Skill")
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise WorkflowError(
            "项目仓库管理暂时无法运行，请修改 project-repository-management Skill 配置后重试"
        ) from exc
    match = re.fullmatch(
        r"---\r?\n(?P<frontmatter>.*?)\r?\n---\r?\n(?P<body>.+)",
        text.strip(),
        flags=re.DOTALL,
    )
    if not match:
        raise WorkflowError(
            "项目仓库管理暂时无法运行，请修改 project-repository-management Skill 配置后重试"
        )
    metadata: dict[str, str] = {}
    for line in match.group("frontmatter").splitlines():
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        metadata[key.strip()] = value.strip()
    if (
        metadata.get("name") != "project-repository-management"
        or not metadata.get("description")
        or "[TODO" in text
        or not match.group("body").strip()
    ):
        raise WorkflowError(
            "项目仓库管理暂时无法运行，请修改 project-repository-management Skill 配置后重试"
        )
    return text.strip()


def application_skill_text(name: str) -> str:
    """Load a bundled launch/operations Skill after fail-closed validation."""

    path = APPLICATION_SKILL_PATHS.get(str(name or ""))
    error_message = f"{name or 'application'} Skill 暂时无法运行，请修改 Skill 配置后重试"
    try:
        if path is None or not path.is_file() or path.stat().st_size > 64_000:
            raise OSError("missing or oversized Skill")
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise WorkflowError(error_message) from exc
    match = re.fullmatch(
        r"---\r?\n(?P<frontmatter>.*?)\r?\n---\r?\n(?P<body>.+)",
        text.strip(),
        flags=re.DOTALL,
    )
    if not match:
        raise WorkflowError(error_message)
    metadata: dict[str, str] = {}
    for line in match.group("frontmatter").splitlines():
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        metadata[key.strip()] = value.strip()
    if (
        metadata.get("name") != name
        or not metadata.get("description")
        or "[TODO" in text
        or not match.group("body").strip()
    ):
        raise WorkflowError(error_message)
    return text.strip()


def prompt_ui_locale(state: dict[str, Any] | None = None, locale: str | None = None) -> str:
    """Resolve the UI/prompt locale for bilingual role templates."""

    raw = str(locale or "")
    if not raw and isinstance(state, dict):
        raw = str(state.get("ui_locale") or state.get("locale") or "")
    if not raw:
        raw = str(os.environ.get("WF_UI_LOCALE") or "zh-CN")
    return "en" if raw.casefold().startswith("en") else "zh-CN"


def public_bubble_language_instruction(locale: str) -> str:
    """Tell the model to write user-visible chat bubbles in the current UI language."""

    if app_i18n.normalize_locale(locale) == app_i18n.EN:
        return (
            "[UI language] The current interface is English. Write user-visible chat "
            "bubbles, trial feedback, task_results.action/evidence, and issue "
            "title/description/actual/expected in English as much as possible. Do not "
            "copy a task_script line in another language; paraphrase it in English. "
            "Proper nouns, button labels, and code identifiers may stay as-is."
        )
    return (
        "【界面语言】当前界面是中文。用户可见的聊天冒泡、体验反馈、task_results.action/"
        "evidence，以及 issues 的 title/description/actual/expected，请尽量用中文撰写。"
        "不要照抄另一种语言的 task_script；按同样意思改写成中文。"
        "专有名词、按钮原文和代码标识可以保留原文。"
    )


def experience_public_report_instruction(locale: str) -> str:
    """Contract for the public fields that become virtual-user chat bubbles."""

    if app_i18n.normalize_locale(locale) == app_i18n.EN:
        return (
            "action is the personal goal you were trying to finish, written in "
            "English as that person would say it, for example \"I wanted to "
            "register my profile so the app could match me\". If task_script is "
            "in another language, paraphrase the same goal instead of copying "
            "it. evidence is what happened at that moment, for example \"When I "
            "tried to fill in my height, the next button stayed grey\". Do not "
            "write checklist lines or synthetic test identities. "
        )
    return (
        "action 写成这个人当时想办成的事，用中文第一人称，例如「我想先登记资料，"
        "好方便帮我匹配」。若 task_script 是另一种语言，按同样意思改写，不要照抄。"
        "evidence 写当时发生了什么，例如「当我填身高的时候，下一步按钮一直是灰的点不了」。"
        "不要写成验收清单，也不要在公开字段里写合成手机号或测试账号。"
    )


def coding_role_prompt(
    prompt_role: str,
    *,
    locale: str | None = None,
    state: dict[str, Any] | None = None,
) -> str:
    """Attach only the product Skills required by the selected role."""

    base_role = (
        "orchestrator"
        if prompt_role in {"coverage_auditor", "reviewer"}
        else prompt_role
    )
    ui_locale = prompt_ui_locale(state, locale)
    role_prompts = ROLE_PROMPTS_EN if ui_locale == "en" else ROLE_PROMPTS
    budget = (
        "\n\n[Context budget] Read only the minimum file range needed for the current task. "
        "Keep search and command output bounded (prefer Glob/Grep, then read specific files; "
        "do not dump full logs, build artifacts, or large files). "
        "After each verifiable small step, return a structured result immediately and avoid accumulating unrelated tool output.\n"
        if ui_locale == "en"
        else (
            "\n\n【上下文预算】只读取完成当前任务所需的最小文件范围。"
            "检索与命令输出必须限量（优先用 Glob/Grep，再读取明确文件；不要输出整份日志、构建产物或大文件）。"
            "每轮完成一个可验证的小步骤后立即给出结构化结果，避免累积无关工具输出。\n"
        )
    )
    base = (
        role_prompts[base_role]
        + budget
        + "\n"
        + public_bubble_language_instruction(ui_locale)
        + "\n"
    )
    if os.environ.get("WF_AGNES_COMPAT") == "1":
        base += (
            "\n\n[OpenAI tool-adapter compatibility]\n"
            "Use only the tools explicitly listed for this turn; do not call TaskOutput; "
            "do not call TaskCreate, TaskUpdate, TaskList, or TaskGet. For Glob, put the glob in `pattern`; `path` "
            "must be a real directory or omitted. Never inspect files outside the current "
            "working directory. Minimize tool calls, then submit StructuredOutput promptly. "
            "Keep nested arrays and objects as native JSON, not JSON-encoded strings. If a "
            "schema requires task_script items shaped as {\"action\":\"...\"}, emit exactly "
            "that object shape rather than a list of strings.\n"
        )
        if prompt_role == "orchestrator":
            base += (
                "For the orchestrator StructuredOutput, the root object must contain "
                "exactly these eight fields and no others: `status`, `summary`, "
                "`questions`, `guardrails`, `required_segments`, "
                "`coverage_dimensions`, `personas`, and `tasks`. Set `status` to "
                "`ready`; `summary` is a required string. Do not wrap this object in "
                "`plan`, `result`, or any role-specific envelope. `guardrails` MUST be "
                "a JSON array, never an object/map or a JSON-encoded string. "
                "Planning is read-only: do not call Write, Edit, Bash, Workflow, or create "
                "a plan file. If Read/Glob/Grep are enabled, inspect only the minimum "
                "existing files; if they are not enabled, use the supplied payload only. "
                "Return the plan exclusively through StructuredOutput. "
                "Every guardrail item must be exactly "
                "{\"text\":\"...\",\"acceptance\":[\"...\"],\"source_quote\":\"...\"}. "
                "Every persona item must contain exactly `id`, `name`, "
                "`covered_segments`, `age`, `gender`, `location`, `role`, "
                "`tech_level`, `device`, `motivation`, `constraints`, `scenario`, "
                "`habits`, and `task_script`; only `covered_segments` and `task_script` "
                "are arrays. In particular, `constraints` and `habits` are strings, and "
                "each `task_script` item is exactly {\"action\":\"...\"}. Every task item "
                "must contain exactly `id`, `title`, `depends_on`, `guardrails`, "
                "`status`, and `verification_mode`; `depends_on` and `guardrails` are "
                "arrays, `status` is `pending`, and qualification tasks use "
                "`verification_mode` = `candidate`. Include every required root field "
                "even when its value is an empty array. "
                "For a qualification app, `required_segments` must contain exactly one "
                "target-user segment, never UI regions, controls, features, or tasks; the "
                "single persona's `covered_segments` must contain that exact same string. "
                "Never put `all_guardrails_satisfied` or `unmet_guardrails` inside "
                "`guardrails`; those fields belong to a different role. `questions`, "
                "`required_segments`, `coverage_dimensions`, `personas`, and `tasks` "
                "must also be JSON arrays even when they contain zero or one item. Emit "
                "one implementation task per independently tryable user-facing capability "
                "(quick entry and a summary dashboard are two tasks, not one title joined "
                "by 'and' or an equivalent conjunction). Task titles must name only the "
                "user-facing feature a participant can try; never include internal "
                "execution context such as P0/P1/P2/P3, ports, manifest-only, credentials, "
                "Experience Twin, CUJ ids, or English variable names. Add one deterministic "
                "verification task that depends on those implementation tasks. "
                "Extract every explicit atomic "
                "constraint in the user's intent as its own guardrail on the first attempt. "
                "The `guardrails` array must not be empty. Each `source_quote` must be one "
                "contiguous verbatim substring copied directly from `intent`; do not "
                "paraphrase it, translate it, or quote a serialized guardrail record. "
                "On a planning retry, preserve every valid prior constraint and add every "
                "omission listed in `previous_problem`; never replace earlier constraints "
                "while fixing new omissions. Before submitting, check each explicit UI, "
                "behavior, persistence, persona-count, technology, testing, and "
                "publish/deploy clause in the intent against a guardrail. "
                "Do not invent process-only archival, sign-off, "
                "deployment, or publication tasks when the user forbids publishing.\n"
            )
        elif prompt_role == "coverage_auditor":
            base += (
                "Use StructuredOutput only; never call ReportFindings. The coverage "
                "StructuredOutput must contain exactly: `passed` boolean; `summary` string; "
                "and `missing_explicit_requirements`, `missing_segments`, "
                "`missing_dimensions`, `persona_issues`, and `questions` as arrays of "
                "strings. Emit empty arrays when there are no findings, with no extra "
                "fields.\n"
            )
        elif prompt_role == "reviewer":
            base += (
                "This turn is independent candidate review, not planning. Use the "
                "minimum read-only product-file inspection and Bash tests needed for evidence. "
                "The candidate preview is workflow-owned runtime: never use `pkill`, `killall`, "
                "or `kill`, never stop or replace the existing preview server, and never run a "
                "process-matching cleanup command. Reuse the running preview and bound every "
                "network probe with a timeout. After one sufficient regression pass, submit "
                "StructuredOutput immediately instead of repeating equivalent checks. "
                "Never inspect `.claude-workflow`, agent/session metadata, conversation or "
                "progress logs, prior verdicts, screenshots from earlier agents, workflow "
                "labels, or condition identifiers. Do not infer which study workflow produced "
                "the artifact. Then submit StructuredOutput with exactly these six root fields and no "
                "others: `summary` string; `guardrails` array of objects shaped "
                "{\"id\":\"...\",\"status\":\"PASS|FAIL|BLOCKED\",\"evidence\":\"...\"}; "
                "`regression` object shaped {\"ran\":true,\"passed\":true,\"commands\":["
                "{\"command\":\"...\",\"exit_code\":0,\"evidence\":\"...\"}]}; `issues` "
                "array of objects shaped {\"title\":\"...\",\"severity\":\"low|medium|high|"
                "critical|blocker\",\"description\":\"...\",\"evidence\":\"...\"}; "
                "`screenshots` array of strings; and `completed_tasks` array of exact task "
                "IDs. Never emit planning fields such as `status`, `questions`, "
                "`personas`, or `tasks`, and never return an empty object.\n"
            )
        elif prompt_role == "developer":
            base += (
                "For Write, always include both `file_path` and `content` in the same tool "
                "call. Every file path must be inside the exact current working directory "
                "shown by `pwd`; never shorten it to `/workspace`. For a small native "
                "single-page app, avoid exploratory probes and use this short sequence: "
                "write the app, write at most one deterministic test script, run it, start "
                "and HTTP-check the preview, then immediately submit StructuredOutput. "
                "Do not create a second test HTML file. In developer StructuredOutput, use "
                "exactly these required shapes: "
                "`summary` string; `ready_for_review` boolean; `changes`, `screenshots`, "
                "`launch_instructions`, `blockers`, and `completed_tasks` arrays of strings; "
                "`tests` an array of objects shaped "
                "{\"command\":\"...\",\"exit_code\":0,\"evidence\":\"...\"}; "
                "`experience_entry` a complete reachable http/https base URL; and "
                "`questions` an array of objects shaped "
                "{\"question\":\"...\",\"options\":[\"...\"]}. Use optional `milestone` "
                "only as a singular boolean; never emit `milestones` or any unlisted field. "
                "For a web app, start a local HTTP server, verify it with an actual HTTP "
                "request, and return a full URL such as `http://127.0.0.1:4173/`; never "
                "return `./index.html`, `/index.html`, a file path, or an unstarted URL. "
                "The preview server is required runtime, not publishing: keep it running "
                "through StructuredOutput and workflow handoff, and never pkill or stop it. "
                "Never bind a reduced debug server, `node -e`, or a generic file server to "
                "the workflow's assigned preview port. Always use the project's real launch "
                "entry and verify that `/` returns 2xx HTML and the primary API journey works "
                "against that same process before returning. "
                "After the final HTTP check, submit StructuredOutput immediately with no "
                "additional grep, find, read-back, or cleanup calls.\n"
            )
    if prompt_role == "operations":
        skills: list[str] = []
        for name in ("application-launch", "application-operations"):
            try:
                skills.append(application_skill_text(name))
            except WorkflowError:
                skills.append(
                    (
                        f"{name} Skill is currently unavailable. Do not invent launch "
                        "configuration, call data sources, or fabricate operations metrics; "
                        "ask the user to repair that Skill configuration and retry."
                    )
                    if ui_locale == "en"
                    else (
                        f"{name} Skill 当前不可用。不得推测上线配置、调用数据源或生成运营指标；"
                        "请向用户提示修改该 Skill 配置后重试。"
                    )
                )
        if ui_locale == "en":
            return (
                base.rstrip()
                + "\n\n[Built-in launch and operations Skills]\n"
                + "\n\n".join(skills)
                + "\n[End of Skills]\n"
            )
        return (
            base.rstrip()
            + "\n\n【内置上线与运营 Skills】\n"
            + "\n\n".join(skills)
            + "\n【Skills 结束】\n"
        )
    if prompt_role != "developer":
        return base
    try:
        skill = project_repository_skill_text()
    except WorkflowError:
        skill = (
            "project-repository-management Skill is currently unavailable. Do not "
            "configure the project repository; ask the user to repair that Skill "
            "configuration and retry."
            if ui_locale == "en"
            else (
                "project-repository-management Skill 当前不可用。不得执行项目仓库配置；"
                "请向用户提示修改该 Skill 配置后重试。"
            )
        )
    if ui_locale == "en":
        return (
            base.rstrip()
            + "\n\n[Built-in project-repository Skill]\n"
            + skill
            + "\n[End of Skill]\n"
        )
    return (
        base.rstrip()
        + "\n\n【内置项目仓库管理 Skill】\n"
        + skill
        + "\n【Skill 结束】\n"
    )


EXPERIENCE_TWIN_MAX_VIEWS = 12
EXPERIENCE_TWIN_MIN_VIEWPORT = 100
EXPERIENCE_TWIN_MAX_VIEWPORT = 8192
EXPERIENCE_TWIN_MAX_CHANGELOG = 100
EXPERIENCE_TWIN_MAX_CHANGELOG_ITEM = 320
_EXPERIENCE_TWIN_VIEW_ID_RE = re.compile(r"[a-z0-9][a-z0-9_-]{0,31}")
_EXPERIENCE_TWIN_LEGACY_VIEW_FIELDS = {"id", "label", "route", "viewport"}
_EXPERIENCE_TWIN_VIEW_FIELDS = _EXPERIENCE_TWIN_LEGACY_VIEW_FIELDS | {
    "surface",
    "platform",
    "device_name",
    "changelog",
}
_EXPERIENCE_TWIN_VIEW_ARTIFACT_FIELDS = _EXPERIENCE_TWIN_VIEW_FIELDS | {"artifact_path"}
_EXPERIENCE_TWIN_NATIVE_ARTIFACT_SUFFIXES = {
    "mobile_app": {".apk", ".ipa", ".hap"},
    "tablet_app": {".apk", ".ipa", ".hap"},
    "watch_app": {".apk", ".ipa", ".hap"},
    "desktop_app": {".exe", ".msix", ".dmg", ".pkg", ".appimage", ".deb"},
}


def _infer_legacy_experience_surface(view_id: str, label: str, width: int, height: int) -> str:
    """Recover a conservative surface kind for pre-metadata persisted views."""

    hint = f"{view_id} {label}".casefold().replace("_", "-")
    if any(token in hint for token in ("watch", "wear", "手表")):
        return "watch_app"
    if any(token in hint for token in ("tablet", "ipad", "pad", "平板")):
        if any(token in hint for token in ("native", "-app", "应用")):
            return "tablet_app"
        return "tablet_web"
    if any(token in hint for token in ("native-app", "native app", "原生应用")):
        if width < 600:
            return "mobile_app"
        if width < 1_000:
            return "tablet_app"
        return "desktop_app"
    if any(
        token in hint
        for token in (
            "mobile",
            "phone",
            "iphone",
            "android",
            "ios",
            "harmony",
            "hongmeng",
            "鸿蒙",
            "手机",
        )
    ):
        if any(token in hint for token in ("web", "browser", "网页", "浏览器")):
            return "mobile_web"
        if any(
            token in hint
            for token in ("native", "-app", "应用", "android", "iphone", "ios", "harmony", "hongmeng", "鸿蒙")
        ):
            return "mobile_app"
        return "mobile_web"
    if any(token in hint for token in ("desktop-app", "desktop app", "native desktop", "桌面应用")):
        return "desktop_app"
    if any(token in hint for token in ("desktop", "web", "browser", "responsive", "电脑", "网页")):
        return "desktop_web"
    # Viewport is used only to migrate old records that had no surface metadata;
    # it never invents an OS or hardware model.
    if width <= 500 and height <= 500:
        return "watch_app"
    if width < 600:
        return "mobile_web"
    if width < 1_000:
        return "tablet_web"
    return "desktop_web"


def _legacy_surface_metadata(surface: str, descriptor: str = "") -> tuple[str, str]:
    """Recover OS evidence without collapsing distinct legacy app targets."""

    hint = str(descriptor or "").casefold().replace("_", "-")
    if any(token in hint for token in ("harmonyos", "harmony os", "hongmeng", "鸿蒙")):
        platform = "HarmonyOS"
    elif any(token in hint for token in ("wearos", "wear os")):
        platform = "Wear OS"
    elif any(token in hint for token in ("watchos", "watch os")):
        platform = "watchOS"
    elif "android" in hint:
        platform = "Android"
    elif re.search(r"(?:^|[^a-z])ios(?:[^a-z]|$)|iphone|ipad", hint):
        platform = "iOS"
    elif "windows" in hint:
        platform = "Windows"
    elif any(token in hint for token in ("macos", "mac os", "macbook")):
        platform = "macOS"
    elif "linux" in hint:
        platform = "Linux"
    else:
        platform = {
            "desktop_web": "Web",
            "mobile_web": "Web",
            "tablet_web": "Web",
        }.get(surface, "Unspecified")

    known_device = re.search(
        r"\b(?:iPhone(?:\s+(?:SE|\d{1,2})(?:\s+(?:Pro(?:\s+Max)?|Plus|Mini))?)?"
        r"|Pixel\s+\d+[A-Za-z]*(?:\s+Pro)?|Galaxy\s+[A-Z]\d+\+?"
        r"|Apple\s+Watch(?:\s+[A-Za-z0-9]+){0,3}"
        r"|Huawei\s+Watch(?:\s+[A-Za-z0-9]+){0,3})\b",
        str(descriptor or ""),
        flags=re.IGNORECASE,
    )
    if known_device:
        device_name = known_device.group(0).strip()
    else:
        device_name = {
            "desktop_web": "Desktop browser",
            "mobile_web": "Mobile browser",
            "tablet_web": "Tablet browser",
            "desktop_app": "Desktop computer",
            "mobile_app": "Mobile device",
            "tablet_app": "Tablet device",
            "watch_app": "Wearable device",
            "other": "Unspecified device",
        }[surface]
    return platform, device_name


def _experience_twin_view_text(value: Any, field: str, index: int) -> str:
    text = str(value or "").strip()
    if not text or len(text) > 80 or any(ord(char) < 32 for char in text):
        raise WorkflowError(f"Experience Twin views[{index}].{field} 必须为 1～80 字符")
    return text


def _experience_twin_changelog(value: Any, index: int) -> list[str]:
    if not isinstance(value, list):
        raise WorkflowError(
            f"Experience Twin views[{index}].changelog 必须是不超过 {EXPERIENCE_TWIN_MAX_CHANGELOG} 条的数组"
        )
    result: list[str] = []
    seen: set[str] = set()
    for item in value[:EXPERIENCE_TWIN_MAX_CHANGELOG]:
        # Changelog copy is presentation metadata, not executable workflow
        # state.  Normalize model verbosity instead of failing an otherwise
        # valid development round and making the user wait for a retry.
        text = re.sub(r"\s+", " ", str(item or "")).strip()
        text = "".join(char for char in text if ord(char) >= 32).strip()
        if not text:
            continue
        if len(text) > EXPERIENCE_TWIN_MAX_CHANGELOG_ITEM:
            text = text[: EXPERIENCE_TWIN_MAX_CHANGELOG_ITEM - 1].rstrip() + "…"
        if text not in seen:
            seen.add(text)
            result.append(text)
    return result


def _experience_twin_entry(value: Any) -> str:
    entry = str(value or "").strip()
    if not entry or len(entry) > 2_048 or any(char.isspace() or ord(char) < 32 for char in entry):
        raise WorkflowError("Experience Twin entry 必须是非空且不超过 2048 字符的完整 http/https URL")
    try:
        parsed = urllib.parse.urlsplit(entry)
    except ValueError as exc:
        raise WorkflowError("Experience Twin entry 不是有效的 Web 地址") from exc
    if parsed.scheme.casefold() not in {"http", "https"} or not parsed.netloc:
        raise WorkflowError("Experience Twin entry 必须是可打开的完整 http/https URL，不能是相对路径")
    if parsed.username is not None or parsed.password is not None:
        raise WorkflowError("Experience Twin entry 不得包含账号或密码")
    try:
        hostname = parsed.hostname
        _ = parsed.port  # Property access validates the port syntax and range.
    except ValueError as exc:
        raise WorkflowError("Experience Twin entry 的主机或端口无效") from exc
    if not hostname:
        raise WorkflowError("Experience Twin entry 必须包含有效主机")
    return entry


def _experience_twin_route(value: Any) -> str:
    route = str(value or "").strip()
    if not route or len(route) > 2_048 or any(ord(char) < 32 for char in route):
        raise WorkflowError("Experience Twin view.route 必须是非空且不超过 2048 字符的路径")
    try:
        parsed = urllib.parse.urlsplit(route)
    except ValueError as exc:
        raise WorkflowError("Experience Twin view.route 不是有效路径") from exc
    if parsed.scheme or parsed.netloc or not route.startswith("/") or route.startswith("//") or "\\" in route:
        raise WorkflowError("Experience Twin view.route 必须是站内绝对路径")
    decoded_parts = urllib.parse.unquote(parsed.path).split("/")
    if any(part == ".." for part in decoded_parts):
        raise WorkflowError("Experience Twin view.route 不得跳出 Preview 根路径")
    return route


def _experience_twin_artifact_path(value: Any, surface: str, platform: str, index: int) -> str:
    artifact_path = str(value or "").strip().replace("\\", "/")
    if not artifact_path:
        return ""
    if len(artifact_path) > 512 or any(ord(char) < 32 for char in artifact_path):
        raise WorkflowError(f"Experience Twin views[{index}].artifact_path 格式无效")
    try:
        parsed = urllib.parse.urlsplit(artifact_path)
    except ValueError as exc:
        raise WorkflowError(f"Experience Twin views[{index}].artifact_path 格式无效") from exc
    if (
        parsed.scheme
        or parsed.netloc
        or parsed.query
        or parsed.fragment
        or artifact_path.startswith("/")
        or re.match(r"^[A-Za-z]:", artifact_path)
    ):
        raise WorkflowError(f"Experience Twin views[{index}].artifact_path 必须是工作区内相对路径")
    parts = parsed.path.split("/")
    if not parts or any(part in {"", ".", ".."} for part in parts):
        raise WorkflowError(f"Experience Twin views[{index}].artifact_path 不得跳出工作区")
    allowed = _EXPERIENCE_TWIN_NATIVE_ARTIFACT_SUFFIXES.get(surface)
    if not allowed:
        raise WorkflowError(f"Experience Twin views[{index}].artifact_path 只允许用于原生应用形态")
    suffix = Path(parsed.path).suffix.casefold()
    if suffix not in allowed:
        raise WorkflowError(
            f"Experience Twin views[{index}].artifact_path 不是该应用形态支持的可安装文件"
        )
    system = platform.casefold()
    platform_suffixes = (
        ({".apk"} if "android" in system else None)
        or ({".ipa"} if system == "ios" or "iphone" in system or "ipad" in system else None)
        or ({".hap"} if "harmony" in system or "鸿蒙" in system else None)
        or ({".exe", ".msix"} if "windows" in system else None)
        or ({".dmg", ".pkg"} if "macos" in system or "mac os" in system else None)
    )
    if platform_suffixes is not None and suffix not in platform_suffixes:
        raise WorkflowError(
            f"Experience Twin views[{index}].artifact_path 与 platform 声明不匹配"
        )
    return parsed.path


def normalize_experience_twin(value: Any) -> dict[str, Any]:
    """Validate and return the canonical, single-runtime Preview contract."""

    if not isinstance(value, dict):
        raise WorkflowError("Experience Twin 必须是对象")
    if set(value) != {"runtime", "entry", "views", "shared_session"}:
        raise WorkflowError("Experience Twin 字段必须是 runtime、entry、views、shared_session")
    if value.get("runtime") != "web_preview":
        raise WorkflowError("Experience Twin runtime 只能是 web_preview")
    if not isinstance(value.get("shared_session"), bool):
        raise WorkflowError("Experience Twin shared_session 必须是布尔值")
    raw_views = value.get("views")
    if not isinstance(raw_views, list) or not 1 <= len(raw_views) <= EXPERIENCE_TWIN_MAX_VIEWS:
        raise WorkflowError(f"Experience Twin views 必须包含 1～{EXPERIENCE_TWIN_MAX_VIEWS} 个视图")
    views: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    semantic_view_indexes: dict[tuple[str, str, str], int] = {}
    for index, raw_view in enumerate(raw_views):
        if not isinstance(raw_view, dict) or frozenset(raw_view) not in {
            frozenset(_EXPERIENCE_TWIN_LEGACY_VIEW_FIELDS),
            frozenset(_EXPERIENCE_TWIN_VIEW_FIELDS),
            frozenset(_EXPERIENCE_TWIN_VIEW_ARTIFACT_FIELDS),
        }:
            raise WorkflowError(f"Experience Twin views[{index}] 字段无效")
        legacy_view = set(raw_view) == _EXPERIENCE_TWIN_LEGACY_VIEW_FIELDS
        view_id = str(raw_view.get("id") or "").strip()
        if not _EXPERIENCE_TWIN_VIEW_ID_RE.fullmatch(view_id):
            raise WorkflowError(f"Experience Twin views[{index}].id 格式无效")
        if view_id in seen_ids:
            raise WorkflowError(f"Experience Twin view.id 重复: {view_id}")
        seen_ids.add(view_id)
        label = _experience_twin_view_text(raw_view.get("label"), "label", index)
        viewport = raw_view.get("viewport")
        if not isinstance(viewport, dict) or set(viewport) != {"width", "height"}:
            raise WorkflowError(f"Experience Twin views[{index}].viewport 字段无效")
        width, height = viewport.get("width"), viewport.get("height")
        if (
            not isinstance(width, int)
            or isinstance(width, bool)
            or not isinstance(height, int)
            or isinstance(height, bool)
            or not EXPERIENCE_TWIN_MIN_VIEWPORT <= width <= EXPERIENCE_TWIN_MAX_VIEWPORT
            or not EXPERIENCE_TWIN_MIN_VIEWPORT <= height <= EXPERIENCE_TWIN_MAX_VIEWPORT
        ):
            raise WorkflowError(
                f"Experience Twin views[{index}].viewport 宽高必须是 "
                f"{EXPERIENCE_TWIN_MIN_VIEWPORT}～{EXPERIENCE_TWIN_MAX_VIEWPORT} 的整数"
            )
        if legacy_view:
            surface = _infer_legacy_experience_surface(view_id, label, width, height)
            platform, device_name = _legacy_surface_metadata(surface, f"{view_id} {label}")
            changelog: list[str] = []
        else:
            surface = str(raw_view.get("surface") or "").strip()
            if surface not in EXPERIENCE_TWIN_SURFACES:
                raise WorkflowError(f"Experience Twin views[{index}].surface 无效")
            platform = _experience_twin_view_text(raw_view.get("platform"), "platform", index)
            device_name = _experience_twin_view_text(raw_view.get("device_name"), "device_name", index)
            changelog = _experience_twin_changelog(raw_view.get("changelog"), index)
        artifact_path = _experience_twin_artifact_path(
            raw_view.get("artifact_path"),
            surface,
            platform,
            index,
        )
        route = _experience_twin_route(raw_view.get("route"))
        canonical_view = {
            "id": view_id,
            "label": label,
            "surface": surface,
            "platform": platform,
            "device_name": device_name,
            "route": route,
            "viewport": {"width": width, "height": height},
            "changelog": changelog,
            "artifact_path": artifact_path,
        }
        semantic_key = (surface, platform.casefold(), device_name.casefold())
        duplicate_index = semantic_view_indexes.get(semantic_key)
        if duplicate_index is not None:
            existing = views[duplicate_index]
            existing_changes = existing["changelog"]
            for change in changelog:
                if change not in existing_changes:
                    existing_changes.append(change)
            continue
        semantic_view_indexes[semantic_key] = len(views)
        views.append(canonical_view)
    return {
        "runtime": "web_preview",
        "entry": _experience_twin_entry(value.get("entry")),
        "views": views,
        "shared_session": value["shared_session"],
    }


def _experience_twin_view_identity(view: dict[str, Any]) -> tuple[str, str, str]:
    return (
        str(view.get("surface") or ""),
        str(view.get("platform") or "").casefold(),
        str(view.get("device_name") or "").casefold(),
    )


def _experience_twin_metadata_is_generic(view: dict[str, Any]) -> bool:
    platform = str(view.get("platform") or "").strip().casefold()
    device = str(view.get("device_name") or "").strip().casefold()
    return platform in {"", "web", "unspecified", "unknown"} or device in {
        "",
        "desktop browser",
        "mobile browser",
        "tablet browser",
        "desktop computer",
        "mobile device",
        "tablet device",
        "wearable device",
        "unspecified device",
    }


def _merge_experience_twin_history(newer: Any, older: Any) -> list[str]:
    result: list[str] = []
    for item in [*(newer or []), *(older or [])]:
        text = str(item or "").strip()
        if text and text not in result:
            result.append(text)
        if len(result) >= EXPERIENCE_TWIN_MAX_CHANGELOG:
            break
    return result


def merge_experience_twins(previous: Any, current: Any) -> dict[str, Any]:
    """Update a Twin without letting one developer round erase other surfaces."""

    current_twin = normalize_experience_twin(current)
    if previous is None:
        return current_twin
    previous_twin = normalize_experience_twin(previous)
    new_views = [dict(view) for view in current_twin["views"]]
    used: set[int] = set()
    merged_views: list[dict[str, Any]] = []

    for old_view in previous_twin["views"]:
        match: int | None = next(
            (
                index
                for index, new_view in enumerate(new_views)
                if index not in used and str(new_view.get("id")) == str(old_view.get("id"))
            ),
            None,
        )
        if match is None:
            match = next(
                (
                    index
                    for index, new_view in enumerate(new_views)
                    if index not in used
                    and _experience_twin_view_identity(new_view) == _experience_twin_view_identity(old_view)
                ),
                None,
            )
        if match is None:
            same_surface = [
                index
                for index, new_view in enumerate(new_views)
                if index not in used and new_view.get("surface") == old_view.get("surface")
            ]
            old_same_surface = [
                view
                for view in previous_twin["views"]
                if view.get("surface") == old_view.get("surface")
            ]
            if (
                len(same_surface) == 1
                and len(old_same_surface) == 1
                and (
                    _experience_twin_metadata_is_generic(old_view)
                    or _experience_twin_metadata_is_generic(new_views[same_surface[0]])
                )
            ):
                match = same_surface[0]
        if match is None:
            merged_views.append(dict(old_view))
            continue
        used.add(match)
        updated = dict(new_views[match])
        updated["changelog"] = _merge_experience_twin_history(
            updated.get("changelog"), old_view.get("changelog")
        )
        merged_views.append(updated)

    merged_views.extend(dict(view) for index, view in enumerate(new_views) if index not in used)
    return normalize_experience_twin({**current_twin, "views": merged_views})


_REQUESTED_EXPERIENCE_SURFACE_PATTERNS: dict[str, re.Pattern[str]] = {
    "desktop_web": re.compile(r"电脑\s*(?:web|网页)|(?:desktop|pc)\s*web|web\s*端", re.IGNORECASE),
    "mobile_web": re.compile(r"手机\s*(?:web|网页)|移动\s*(?:web|网页)|mobile\s*web|\bh5\b", re.IGNORECASE),
    "mobile_app": re.compile(r"手机\s*(?:原生\s*)?(?:app|应用)|手机原生|mobile\s*(?:native\s*)?app|(?:android|ios|鸿蒙)\s*app", re.IGNORECASE),
    "watch_app": re.compile(r"手表(?:端|应用)|智能手表|watch\s*app|wear\s*os", re.IGNORECASE),
    "tablet_web": re.compile(r"平板\s*(?:web|网页)|tablet\s*web", re.IGNORECASE),
    "tablet_app": re.compile(r"平板\s*(?:app|应用)|tablet\s*app", re.IGNORECASE),
    "desktop_app": re.compile(r"(?:电脑|桌面)\s*(?:app|应用)|desktop\s*app", re.IGNORECASE),
}


def requested_experience_surfaces(state: dict[str, Any]) -> set[str]:
    evidence: list[str] = [str(state.get("intent") or "")]
    for task in state.get("tasks") or []:
        if isinstance(task, dict):
            evidence.extend(str(task.get(key) or "") for key in ("title", "description", "acceptance"))
    if state.get("guardrail_store") or state.get("guardrail_file"):
        guardrails = active_guardrails(state)
    else:
        # Unit callers and migrated snapshots can carry an inline mirror before
        # the append-only guardrail store is available.
        guardrails = [row for row in state.get("guardrail_history") or [] if isinstance(row, dict)]
    for guardrail in guardrails:
        evidence.append(json.dumps(guardrail, ensure_ascii=False, sort_keys=True))
    text = "\n".join(evidence)
    return {
        surface
        for surface, pattern in _REQUESTED_EXPERIENCE_SURFACE_PATTERNS.items()
        if pattern.search(text)
    }


def paired_study_default_web_views_enabled(state: dict[str, Any]) -> bool:
    """Whether desktop and mobile Web views are always available."""

    return True


def ensure_paired_study_default_web_views(
    state: dict[str, Any], twin: dict[str, Any]
) -> dict[str, Any]:
    """Backfill the paired study's two default Web views without losing state."""

    if not paired_study_default_web_views_enabled(state):
        return twin
    views = [dict(view) for view in twin.get("views") or [] if isinstance(view, dict)]
    present = {str(view.get("surface") or "") for view in views}
    if all(surface in present for surface in DEFAULT_STUDY_WEB_EXPERIENCE_SURFACES):
        return twin
    route = next(
        (
            str(view.get("route") or "/")
            for view in views
            if str(view.get("surface") or "") in WEB_EXPERIENCE_SURFACES
        ),
        "/",
    )
    used_ids = {str(view.get("id") or "") for view in views}
    for surface in DEFAULT_STUDY_WEB_EXPERIENCE_SURFACES:
        if surface in present:
            continue
        preferred_id, label, device_name, width, height = _DEFAULT_STUDY_WEB_VIEW_CATALOG[surface]
        view_id = preferred_id
        suffix = 2
        while view_id in used_ids:
            view_id = f"{preferred_id}-{suffix}"
            suffix += 1
        used_ids.add(view_id)
        present.add(surface)
        views.append(
            {
                "id": view_id,
                "label": label,
                "surface": surface,
                "platform": "Web",
                "device_name": device_name,
                "route": route,
                "viewport": {"width": width, "height": height},
                "changelog": [],
            }
        )
    return normalize_experience_twin({**twin, "views": views})


def sync_paired_study_default_surface_records(
    state: dict[str, Any], twin: dict[str, Any]
) -> bool:
    """Keep the legacy surface list from hiding a view present in the Twin."""

    if not paired_study_default_web_views_enabled(state):
        return False
    raw = state.get("experience_surfaces")
    records = [dict(item) if isinstance(item, dict) else item for item in raw] if isinstance(raw, list) else []
    present = {
        str(item.get("surface") or item.get("surface_type") or "")
        for item in records
        if isinstance(item, dict)
    }
    changed = not isinstance(raw, list)
    for view in twin.get("views") or []:
        if not isinstance(view, dict):
            continue
        surface = str(view.get("surface") or "")
        if surface not in DEFAULT_STUDY_WEB_EXPERIENCE_SURFACES or surface in present:
            continue
        records.append(dict(view))
        present.add(surface)
        changed = True
    if changed:
        state["experience_surfaces"] = records
    return changed


def developmental_experience_round_limit(state: dict[str, Any] | None = None) -> int:
    """Return the single AppLooper loop budget.

    One loop is a complete feedback-to-optimize cycle, not an internal
    develop/review micro-tick. The workflow ``max_rounds`` is the source of
    truth; the env var remains a test-only override.
    """

    fallback = APPLOOPER_DEVELOPMENTAL_EXPERIENCE_ROUNDS_DEFAULT
    if isinstance(state, dict):
        with contextlib.suppress(TypeError, ValueError, OverflowError):
            fallback = max(
                1,
                min(
                    APPLOOPER_DEVELOPMENTAL_EXPERIENCE_ROUNDS_MAX,
                    int(state.get("max_rounds") or fallback),
                ),
            )
    raw = os.environ.get("WF_APPLOOPER_DEVELOPMENTAL_EXPERIENCE_ROUNDS")
    if raw not in {None, ""}:
        with contextlib.suppress(TypeError, ValueError, OverflowError):
            return max(0, min(APPLOOPER_DEVELOPMENTAL_EXPERIENCE_ROUNDS_MAX, int(raw)))
    return fallback


def treatment_loop_count(state: dict[str, Any]) -> int:
    with contextlib.suppress(TypeError, ValueError, OverflowError):
        return max(0, int(state.get("developmental_experience_rounds") or 0))
    return 0


def study_preview_port(state: dict[str, Any]) -> int | None:
    """Read only the server-authored, workflow-specific loopback port contract."""

    intent = str(state.get("intent") or "")
    match = re.search(
        r"(?:bind\s+to|必须绑定)\s*127\.0\.0\.1:(\d{4,5})(?!\d)",
        intent,
        re.IGNORECASE,
    )
    if not match:
        return None
    port = int(match.group(1))
    return port if 1024 <= port <= 65535 else None


class _NoPreviewRedirect(urllib.request.HTTPRedirectHandler):
    """Keep preview recovery on the exact allocated loopback origin."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):  # type: ignore[no-untyped-def]
        return None


def _recovered_preview_views(state: dict[str, Any]) -> list[dict[str, Any]]:
    requested = requested_experience_surfaces(state)
    web_surfaces = [
        surface
        for surface in ("desktop_web", "mobile_web", "tablet_web")
        if surface in requested
    ]
    if paired_study_default_web_views_enabled(state):
        web_surfaces = list(DEFAULT_STUDY_WEB_EXPERIENCE_SURFACES) + [
            surface for surface in web_surfaces if surface not in DEFAULT_STUDY_WEB_EXPERIENCE_SURFACES
        ]
    elif not web_surfaces:
        web_surfaces = ["desktop_web"]
    catalog = {
        "desktop_web": ("desktop", "电脑网页端", "Desktop browser", 1280, 800),
        "mobile_web": ("mobile", "手机网页端", "Mobile browser", 390, 844),
        "tablet_web": ("tablet", "平板网页端", "Tablet browser", 820, 1180),
    }
    views: list[dict[str, Any]] = []
    for surface in web_surfaces:
        view_id, label, device_name, width, height = catalog[surface]
        views.append(
            {
                "id": view_id,
                "label": label,
                "surface": surface,
                "platform": "Web",
                "device_name": device_name,
                "route": "/",
                "viewport": {"width": width, "height": height},
                "changelog": ["从当前工作流已启动的受控试用端口恢复"],
            }
        )
    return views


def recover_study_preview_checkpoint(state: dict[str, Any]) -> bool:
    """Persist a runnable AppLooper preview even if the developer envelope was lost.

    The endpoint is never guessed or scanned: it must be the loopback port that
    ``workflow_web`` embedded in the signed study intent. Redirects are disabled,
    and a bounded HTML response is required before any Experience Twin is saved.
    """

    if not study_multi_agent_treatment_enabled(state):
        return False
    existing = experience_twin_from_state(state)
    if existing is not None:
        return False
    port = study_preview_port(state)
    if port is None:
        return False
    entry = f"http://127.0.0.1:{port}/"
    opener = urllib.request.build_opener(_NoPreviewRedirect())
    request = urllib.request.Request(
        entry,
        headers={"User-Agent": "AppLooper-Preview-Recovery/1.0", "Accept": "text/html"},
        method="GET",
    )
    try:
        with opener.open(request, timeout=3) as response:
            status = int(getattr(response, "status", 0) or 0)
            content_type = str(response.headers.get("Content-Type") or "").casefold()
            body = response.read(65_537)
    except (OSError, ValueError, urllib.error.URLError, urllib.error.HTTPError):
        return False
    lowered = body[:65_536].lstrip().lower()
    html_response = "text/html" in content_type or lowered.startswith(b"<!doctype html") or b"<html" in lowered[:4096]
    if status < 200 or status >= 300 or len(body) > 65_536 or not html_response:
        return False
    twin = normalize_experience_twin(
        {
            "runtime": "web_preview",
            "entry": entry,
            "views": _recovered_preview_views(state),
            "shared_session": True,
        }
    )
    validate_experience_twin_completeness(state, twin)
    state["experience_twin"] = twin
    state["experience_surfaces"] = [dict(view) for view in twin["views"]]
    checkpoints = [
        row for row in state.get("development_checkpoints") or [] if isinstance(row, dict)
    ]
    checkpoint = {
        "at": utcnow(),
        "kind": "recovered_runnable_preview",
        "entry": entry,
        "candidate_id": candidate_fingerprint(state),
        "source": "allocated_preview_port_probe",
    }
    checkpoints.append(checkpoint)
    state["development_checkpoints"] = checkpoints[-20:]
    event(
        state,
        "development_preview_recovered",
        candidate_id=checkpoint["candidate_id"],
        entry=entry,
        views=len(twin["views"]),
    )
    return True


def usable_development_preview_checkpoint(state: dict[str, Any]) -> bool:
    """Whether AppLooper already has a complete preview that can enter testing.

    A worker may stop after the preview has been recovered but before the
    developmental Experience phase is persisted.  Treat that durable preview
    as a valid anti-stall checkpoint on the next worker attempt instead of
    sending the developer back through the same failed command loop.
    """

    if not study_multi_agent_treatment_enabled(state):
        return False
    twin = experience_twin_from_state(state)
    if twin is None:
        return False
    try:
        validate_experience_twin_completeness(state, twin)
    except WorkflowError:
        return False
    port = study_preview_port(state)
    entry = str(twin.get("entry") or "").rstrip("/") + "/"
    if port is None or entry != f"http://127.0.0.1:{port}/":
        return False
    opener = urllib.request.build_opener(_NoPreviewRedirect())
    request = urllib.request.Request(
        entry,
        headers={"User-Agent": "AppLooper-Preview-Checkpoint/1.0", "Accept": "text/html"},
        method="GET",
    )
    try:
        with opener.open(request, timeout=3) as response:
            status = int(getattr(response, "status", 0) or 0)
            content_type = str(response.headers.get("Content-Type") or "").casefold()
            body = response.read(65_537)
    except (OSError, ValueError, urllib.error.URLError, urllib.error.HTTPError):
        return False
    lowered = body[:65_536].lstrip().lower()
    html_response = (
        "text/html" in content_type
        or lowered.startswith(b"<!doctype html")
        or b"<html" in lowered[:4096]
    )
    return 200 <= status < 300 and len(body) <= 65_536 and html_response


