_LOGIN_BLOCKER_RE = re.compile(
    r"登录|登陆|注册|sign[\s-]?in|sign[\s-]?up|log[\s-]?in|register|"
    r"手机号|手机验证|短信|验证码|邮箱验证|real phone|verification code|"
    r"未登录|not logged|authentication required|auth required|需要登录",
    re.I,
)

_AUTH_CUJ_RE = re.compile(
    r"注册|登录|登陆|\bsign[\s-]?up\b|\bsign[\s-]?in\b|\blog[\s-]?in\b|"
    r"\bregister\b|账号|\baccount\b|\bauth(?:entication|orization)?\b|手机号|邮箱",
    re.I,
)
_MOBILE_DEVICE_RE = re.compile(r"mobile|手机|android|ios|iphone|pixel|移动端|h5", re.I)
_FORM_FIELD_MISMATCH_RE = re.compile(
    r"(?:手机|phone|mobile).{0,24}(?:邮箱|email)|(?:邮箱|email).{0,24}(?:手机|phone|mobile)",
    re.I,
)
AUTH_CUJ_DETECTION_VERSION = 4
_INJECTED_AUTH_CUJ_STEP_IDS = frozenset({"cuj01", "cuj02", "cuj03", "cuj04"})

SYNTHETIC_PHONE = "13800138000"
SYNTHETIC_EMAIL = "testuser@example.test"
SYNTHETIC_OTP = "000000"

EUFR_P0_OPEN_STATUSES = frozenset({"collected", "acknowledged", "in_progress"})
EUFR_BETA_PHASES = frozenset({"REVIEW", "EXPERIENCE", "DELIVER", "DELIVERED", "WAIT_USER", "REPLAY", "DEVELOP"})

EXPERIENCE_CUJ_POLICY = (
    "交付前必须通过注册/登录 CUJ：允许在注册 UI 使用合成数据（手机号 13800138000、邮箱 testuser@example.test、验证码 000000 或 staging mock OTP），"
    "禁止真实 PII 与真实 SMS。必须做表单校验横向检查：字段类型与错误文案不得交叉（如手机号字段不得提示邮箱格式错误）。"
)


def experience_auth_cuj_prompt(state: dict[str, Any]) -> str:
    if app_requires_auth_cuj(state):
        return (
            EXPERIENCE_CUJ_POLICY
            + " 若 persona_initial_state 指定 test_account，必须先按 auth_notes 完成登录再执行需鉴权的步骤；"
            "注册 CUJ 允许合成手机号/邮箱/验证码，禁止真实 PII 与真实 SMS。"
        )
    return " task_script 未包含注册或登录 CUJ 时，不得自行新增认证、手机号、验证码或账号测试。"


def experience_result_for_prompt(result: dict[str, Any]) -> dict[str, Any]:
    """Project a host-enriched result back onto the provider schema.

    Host-only provenance such as ``triage_type`` and verification gaps must not
    be shown as if they were provider output fields; otherwise a later model
    turn can copy them and fail the strict schema it was asked to produce.
    """

    issue_keys = {
        "title", "severity", "description", "steps", "expected", "actual",
        "screenshot", "affected_guardrails", "change_scope", "confidence",
    }
    return {
        "persona_id": str(result.get("persona_id") or ""),
        "platform": str(result.get("platform") or ""),
        "computer_use_attempted": bool(result.get("computer_use_attempted")),
        "computer_use_succeeded": bool(result.get("computer_use_succeeded")),
        "computer_use_tools": [str(item) for item in result.get("computer_use_tools") or []],
        "task_results": [
            {
                "step_id": str(item.get("step_id") or ""),
                "status": str(item.get("status") or ""),
                "evidence": str(item.get("evidence") or ""),
            }
            for item in result.get("task_results") or []
            if isinstance(item, dict)
        ],
        "satisfied": bool(result.get("subjective_satisfied", result.get("satisfied"))),
        "issues": [
            {key: item.get(key) for key in issue_keys if key in item}
            for item in result.get("issues") or []
            if isinstance(item, dict)
        ],
        "screenshots": [str(item) for item in result.get("screenshots") or []],
        "blocker": str(result.get("blocker") or ""),
    }


def experience_batch_identity(
    state: dict[str, Any],
    candidate_id: str,
    guardrail_set_id: str,
    cohort_ids: list[str],
) -> str:
    protocol = normalize_study_evaluation_protocol(state.get("study_evaluation_protocol"))
    shared_cuj_id = str((protocol or {}).get("shared_cuj", {}).get("id") or "none")
    return (
        f"{candidate_id}:{guardrail_set_id}:r{state.get('round', 0)}:"
        f"{','.join(cohort_ids)}:auth-cuj-v{AUTH_CUJ_DETECTION_VERSION}-"
        f"{int(app_requires_auth_cuj(state))}:shared-cuj-{shared_cuj_id}"
    )


def app_requires_auth_cuj(state: dict[str, Any]) -> bool:
    cached = state.get("cuj_required")
    cache_current = state.get("cuj_detection_version") == AUTH_CUJ_DETECTION_VERSION
    if cache_current and cached is False:
        return False
    if cache_current and cached is True:
        return True
    corpus_parts = [
        str(state.get("intent") or ""),
        str(state.get("plan_summary") or ""),
    ]
    if state.get("guardrail_file") or state.get("guardrail_store"):
        corpus_parts.append(
            " ".join(str(item.get("text") or "") for item in active_guardrails(state) if isinstance(item, dict))
        )
    corpus = " ".join(corpus_parts)
    if _AUTH_CUJ_RE.search(corpus):
        state["cuj_required"] = True
        state["cuj_detection_version"] = AUTH_CUJ_DETECTION_VERSION
        return True
    # Persona scripts are model-generated test plans, not user requirements.
    # Treating phrases such as "登录应用后进入概览" as proof that the product
    # needs account authentication can inject unrelated registration CUJs and
    # create an endless experience loop. Auth CUJs therefore come only from
    # the intent, plan summary, or active user guardrails above.
    state["cuj_required"] = False
    state["cuj_detection_version"] = AUTH_CUJ_DETECTION_VERSION
    return False


def build_cuj_task_steps() -> list[dict[str, str]]:
    return [
        {"id": "cuj01", "action": "打开注册页面（优先使用手机视图 mobile_web）"},
        {
            "id": "cuj02",
            "action": (
                f"在手机号字段输入合成测试号码 {SYNTHETIC_PHONE}（禁止真实手机号），"
                f"尝试获取验证码；若环境提供固定测试码则输入 {SYNTHETIC_OTP}，否则只验证表单校验与错误提示"
            ),
        },
        {
            "id": "cuj03",
            "action": "确认手机号字段的错误提示不得要求邮箱格式；若字段类型与错误文案不一致，记录为阻断问题并截图",
        },
        {
            "id": "cuj04",
            "action": "使用 test_account 或合成账号完成登录流程验证（禁止真实 PII/SMS）",
        },
    ]


def select_cuj_carrier_persona_id(cohort: list[dict[str, Any]]) -> str:
    for persona in cohort:
        if not isinstance(persona, dict):
            continue
        device = public_field(persona.get("device"))
        if _MOBILE_DEVICE_RE.search(device):
            return str(persona.get("id") or "")
    if cohort and isinstance(cohort[0], dict):
        return str(cohort[0].get("id") or "")
    return ""


def bound_experience_core_script(
    script: list[Any],
    *,
    limit: int = EXPERIENCE_FIRST_ROUND_MAX_STEPS,
) -> list[dict[str, Any]]:
    """Keep a first-round virtual-user script to 3–5 core actions."""

    bounded: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    seen_actions: set[str] = set()
    for row in script:
        if not isinstance(row, dict):
            continue
        action = str(row.get("action") or "").strip()
        if not action:
            continue
        step_id = str(row.get("id") or "").strip()
        if step_id and step_id in seen_ids:
            continue
        if action in seen_actions:
            continue
        bounded.append(dict(row))
        if step_id:
            seen_ids.add(step_id)
        seen_actions.add(action)
        if len(bounded) >= max(1, int(limit)):
            break
    return bounded


def experience_persona_script(
    state: dict[str, Any],
    persona: dict[str, Any],
    cohort: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    script = [dict(row) for row in persona.get("task_script") or [] if isinstance(row, dict)]
    if not app_requires_auth_cuj(state):
        script = [
            row for row in script
            if str(row.get("id") or "") not in _INJECTED_AUTH_CUJ_STEP_IDS
        ]
    script = bound_experience_core_script(script)
    carrier_id = select_cuj_carrier_persona_id(cohort)
    if str(persona.get("id") or "") != carrier_id:
        return script
    existing_ids = {str(row.get("id") or "") for row in script}
    existing_actions = {str(row.get("action") or "") for row in script}
    required_steps = study_shared_cuj_steps(state)
    if app_requires_auth_cuj(state):
        required_steps.extend(build_cuj_task_steps())
    for step in required_steps:
        action = str(step.get("action") or "")
        step_id = str(step.get("id") or "")
        if action in existing_actions or step_id in existing_ids:
            continue
        script.append({"id": step_id, "action": action})
    return script


def experience_follow_up_script(previous_results: list[dict[str, Any]]) -> list[dict[str, str]]:
    """Keep later virtual-user turns on the issues that person already raised."""

    titles: list[str] = []
    for row in previous_results:
        if not isinstance(row, dict):
            continue
        for issue in row.get("issues") or []:
            if not isinstance(issue, dict):
                continue
            title = public_observation_field(issue.get("title")) or public_field(issue.get("title"))
            title = re.sub(r"\s+", " ", str(title or "")).strip()
            if not title or _EXPERIENCE_DEVELOPER_VOICE_RE.search(title):
                continue
            if title not in titles:
                titles.append(title[:40])
            if len(titles) >= 3:
                break
        if len(titles) >= 3:
            break
    return [
        {"id": f"follow-up-{index}", "action": f"再试一次：{title}"}
        for index, title in enumerate(titles, 1)
    ]


def form_validation_issues_in_result(result: dict[str, Any]) -> list[str]:
    issues: list[str] = []
    for raw in result.get("issues") or []:
        if not isinstance(raw, dict):
            continue
        title = str(raw.get("title") or "")
        description = str(raw.get("description") or "")
        actual = str(raw.get("actual") or "")
        blob = f"{title} {description} {actual}"
        if _FORM_FIELD_MISMATCH_RE.search(blob):
            issues.append(title or "表单字段类型与错误文案不一致")
    for gap in result.get("verification_gaps") or []:
        if not isinstance(gap, dict):
            continue
        reason = str(gap.get("reason") or "")
        if _FORM_FIELD_MISMATCH_RE.search(reason):
            issues.append(reason)
    return list(dict.fromkeys(item for item in issues if item))


def update_cuj_gate_from_experience(
    state: dict[str, Any],
    results: list[dict[str, Any]],
    cohort: list[dict[str, Any]],
) -> dict[str, Any]:
    shared_steps = study_shared_cuj_steps(state)
    auth_steps = build_cuj_task_steps() if app_requires_auth_cuj(state) else []
    required_steps = [*shared_steps, *auth_steps]
    if not required_steps:
        gate = {"required": False, "passed": True, "failures": [], "verified_at": utcnow()}
        state["cuj_gate"] = gate
        return gate
    carrier_id = select_cuj_carrier_persona_id(cohort)
    carrier_result = next(
        (row for row in results if isinstance(row, dict) and str(row.get("persona_id") or "") == carrier_id),
        None,
    )
    failures: list[str] = []
    if not carrier_id:
        failures.append("缺少 CUJ 载体画像")
    elif not isinstance(carrier_result, dict):
        failures.append("缺少 CUJ 载体画像的体验结果")
    else:
        carrier_persona = next(
            (row for row in cohort if isinstance(row, dict) and str(row.get("id") or "") == carrier_id),
            {},
        )
        carrier_script = experience_persona_script(state, carrier_persona, cohort)
        if not experience_passed(state, carrier_result, expected_script=carrier_script):
            failures.append("CUJ 载体画像体验未全部通过")
        task_results = {
            str(row.get("step_id") or ""): row
            for row in carrier_result.get("task_results") or []
            if isinstance(row, dict)
        }
        for step in required_steps:
            step_id = str(step.get("id") or "")
            row = task_results.get(step_id)
            if not row or str(row.get("status") or "").upper() != "PASS":
                failures.append(f"关键路径步骤未通过：{step.get('action', '')[:72]}")
        if auth_steps:
            failures.extend(form_validation_issues_in_result(carrier_result))
    gate = {
        "required": True,
        "passed": not failures,
        "failures": failures,
        "carrier_persona_id": carrier_id,
        "shared_cuj_id": str(
            (normalize_study_evaluation_protocol(state.get("study_evaluation_protocol")) or {})
            .get("shared_cuj", {})
            .get("id", "")
        ),
        "expected_step_ids": [str(step.get("id") or "") for step in required_steps],
        "verified_at": utcnow(),
    }
    state["cuj_gate"] = gate
    return gate


def cuj_gate_passed(state: dict[str, Any]) -> bool:
    gate = state.get("cuj_gate") if isinstance(state.get("cuj_gate"), dict) else {}
    if not gate.get("required"):
        return True
    return bool(gate.get("passed"))


def flag_eufr_p0_pending(state: dict[str, Any], theme: dict[str, Any]) -> None:
    if str(theme.get("priority") or "").upper() != "P0":
        return
    if str(theme.get("status") or "").casefold() not in EUFR_P0_OPEN_STATUSES:
        return
    theme_id = str(theme.get("id") or "").strip()
    if not theme_id:
        return
    pending = state.setdefault("pending_eufr_p0", [])
    if not isinstance(pending, list):
        pending = state["pending_eufr_p0"] = []
    if theme_id in {str(item) for item in pending}:
        return
    pending.append(theme_id)
    event(state, "eufr_p0_queued", theme_id=theme_id, title=str(theme.get("title") or "")[:160])


def process_eufr_p0_feedback_cycle(state: dict[str, Any], mailer: Mailer | WebChannel) -> bool:
    pending_raw = state.get("pending_eufr_p0")
    pending = [str(item) for item in pending_raw if str(item)] if isinstance(pending_raw, list) else []
    if not pending:
        return False
    phase = str(state.get("phase") or "").upper()
    if phase not in EUFR_BETA_PHASES:
        return False
    if phase in {"EXPERIENCE", "REVIEW"} and str(state.get("status") or "") == "running":
        return False
    if state.get("pending_user"):
        return False
    model, storage = _read_operations_model(state)
    if storage == "none":
        return False
    themes = model.get("eufr_themes") if isinstance(model.get("eufr_themes"), list) else []
    theme_id = pending[0]
    theme = next((row for row in themes if isinstance(row, dict) and str(row.get("id") or "") == theme_id), None)
    state["pending_eufr_p0"] = pending[1:]
    if not isinstance(theme, dict):
        save_state(state)
        return True
    if str(theme.get("priority") or "").upper() != "P0":
        save_state(state)
        return True
    if str(theme.get("status") or "").casefold() not in EUFR_P0_OPEN_STATUSES:
        save_state(state)
        return True
    title = public_non_question_text(theme.get("title"), "P0 用户反馈")[:160]
    summary = public_non_question_text(theme.get("summary"), "")[:1000]
    theme["status"] = "in_progress"
    theme["updated_at"] = utcnow()
    _write_operations_model(state, model, storage)
    state["feedback"] = [
        {
            "source": "eufr_explicit",
            "priority": "P0",
            "theme_id": theme_id,
            "gate_failures": [f"P0 显式用户反馈：{title}"],
            "issues": [
                {
                    "title": title,
                    "severity": "blocker",
                    "description": summary or title,
                    "change_scope": "bug",
                }
            ],
        }
    ]
    state["phase"] = "DEVELOP"
    state["status"] = "running"
    set_public_work_summary(
        state,
        kind="developing",
        current=f"处理 P0 显式用户反馈：{title}",
        next_step="修复后重新验收与体验测试",
    )
    event(state, "eufr_p0_development_started", theme_id=theme_id, title=title)
    save_state(state)
    return True


def normalize_persona_initial_state(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    account = public_field(value.get("test_account"))
    auth_mode = str(value.get("auth_mode") or "").strip().lower()
    if auth_mode not in {"anonymous", "test_account"}:
        auth_mode = "test_account" if account else "anonymous"
    if auth_mode == "anonymous" and not account:
        return None
    source = str(value.get("source") or "manual").strip().lower()
    if source not in {"plan", "orchestrator", "manual"}:
        source = "manual"
    notes = lifecycle_safe_text(value.get("auth_notes"), limit=400)
    if account and not notes:
        notes = f"使用为本画像预置的测试账号「{account}」登录；注册/登录 CUJ 可使用合成手机号 {SYNTHETIC_PHONE} 与测试验证码 {SYNTHETIC_OTP}，禁止真实 PII 与真实 SMS。"
    return {
        "auth_mode": auth_mode,
        "test_account": account,
        "auth_notes": notes,
        "avoid_real_phone": bool(value.get("avoid_real_phone", True)),
        "source": source,
        "adjusted_reason": lifecycle_safe_text(value.get("adjusted_reason"), limit=240),
        "updated_at": public_field(value.get("updated_at")) or utcnow(),
    }


def derive_test_account_username(persona: dict[str, Any]) -> str:
    existing = normalize_persona_initial_state(persona.get("initial_state"))
    if existing and existing.get("test_account"):
        return str(existing["test_account"])
    name = public_field(persona.get("name"))
    ascii_match = re.findall(r"\b[a-z][a-z0-9_]{2,}\b", name, re.I)
    if ascii_match:
        return ascii_match[0].lower()[:32]
    persona_id = re.sub(r"[^a-zA-Z0-9_-]", "-", str(persona.get("id") or "")).strip("-").lower()
    if persona_id and not re.fullmatch(r"p\d+", persona_id):
        slug = re.sub(r"[^a-z0-9]+", "", persona_id)
        if len(slug) >= 3:
            return slug[:32]
    return f"vu_{persona_id or 'test'}"[:32]


def persona_initial_state_for_experience(persona: dict[str, Any]) -> dict[str, Any] | None:
    raw = normalize_persona_initial_state(persona.get("initial_state"))
    if not raw or raw.get("auth_mode") != "test_account":
        return None
    account = public_field(raw.get("test_account"))
    if not account:
        return None
    return {
        "auth_mode": "test_account",
        "test_account": account,
        "auth_notes": public_field(raw.get("auth_notes")) or f"使用测试账号 {account} 登录；注册 CUJ 可使用合成手机号 {SYNTHETIC_PHONE}，禁止真实 PII/SMS。",
        "avoid_real_phone": bool(raw.get("avoid_real_phone", True)),
    }


def experience_has_login_blocker(result: dict[str, Any]) -> bool:
    if not isinstance(result, dict):
        return False
    texts: list[str] = []
    blocker = public_field(result.get("blocker"))
    if blocker:
        texts.append(blocker)
    for gap in result.get("verification_gaps") or []:
        if isinstance(gap, dict):
            texts.append(public_field(gap.get("reason")))
            if str(gap.get("triage_type") or "").lower() == "environment_blocker":
                texts.append(public_field(gap.get("reason")))
    for task in result.get("task_results") or []:
        if not isinstance(task, dict):
            continue
        if str(task.get("status") or "").upper() == "BLOCKED":
            texts.append(public_field(task.get("evidence")))
    for issue in result.get("issues") or []:
        if not isinstance(issue, dict):
            continue
        texts.extend(
            public_field(item)
            for item in (issue.get("title"), issue.get("description"), issue.get("actual"))
            if public_field(item)
        )
    joined = " ".join(texts)
    return bool(joined and _LOGIN_BLOCKER_RE.search(joined))


def persona_login_blocker_history_count(state: dict[str, Any], persona_id: str) -> int:
    count = 0
    for row in state.get("last_experience") or []:
        if isinstance(row, dict) and str(row.get("persona_id") or "") == persona_id and experience_has_login_blocker(row):
            count += 1
    return count


def build_persona_initial_state(
    persona: dict[str, Any],
    *,
    test_account: str,
    reason: str,
    source: str = "orchestrator",
    auth_notes: str = "",
) -> dict[str, Any]:
    account = re.sub(r"[^a-zA-Z0-9_.-]", "", str(test_account or "").strip().lower())[:32]
    if not account:
        account = derive_test_account_username(persona)
    notes = lifecycle_safe_text(auth_notes, limit=400) or (
        f"使用为本画像预置的测试账号「{account}」登录；不要使用真实手机号或邮箱注册。"
    )
    return normalize_persona_initial_state(
        {
            "auth_mode": "test_account",
            "test_account": account,
            "auth_notes": notes,
            "avoid_real_phone": True,
            "source": source,
            "adjusted_reason": reason,
            "updated_at": utcnow(),
        }
    ) or {}


def suggest_persona_initial_states_via_orchestrator(
    state: dict[str, Any],
    personas: list[dict[str, Any]],
    *,
    reason: str,
) -> dict[str, dict[str, str]]:
    if not personas:
        return {}
    payload = {
        "task": (
            "为以下虚拟用户生成差异化测试账号用户名（test_account），用于绕过真实手机号/邮箱登录。"
            "中文姓名请转拼音小写且不含空格（如赵启明→zhaoqiming，许远→xuyuan）。"
            "不得返回密码、token 或密钥。auth_notes 用一句话说明使用该测试账号登录。"
        ),
        "reason": reason[:400],
        "personas": [
            {
                "persona_id": str(persona.get("id") or ""),
                "name": public_field(persona.get("name")),
                "role": public_field(persona.get("role")),
                "fallback_account": derive_test_account_username(persona),
            }
            for persona in personas
            if isinstance(persona, dict)
        ],
    }
    try:
        result = call_claude(
            state,
            "orchestrator",
            prompt_json("生成虚拟用户测试账号", payload),
            PERSONA_INITIAL_STATE_SUGGEST_SCHEMA,
            writable=False,
        )
    except Exception as exc:
        event(state, "persona_initial_state_suggest_failed", error=str(exc)[:300])
        return {}
    suggestions: dict[str, dict[str, str]] = {}
    for row in result.get("accounts") or []:
        if not isinstance(row, dict):
            continue
        persona_id = str(row.get("persona_id") or "").strip()
        account = re.sub(r"[^a-zA-Z0-9_.-]", "", str(row.get("test_account") or "").strip().lower())[:32]
        if persona_id and account:
            suggestions[persona_id] = {
                "test_account": account,
                "auth_notes": lifecycle_safe_text(row.get("auth_notes"), limit=400),
            }
    return suggestions


def maybe_adjust_persona_initial_states_from_experience(
    state: dict[str, Any],
    results: list[dict[str, Any]],
) -> list[str]:
    personas = [item for item in (state.get("personas") or []) if isinstance(item, dict)]
    if not personas:
        return []
    current_login: dict[str, bool] = {}
    for row in results:
        if not isinstance(row, dict):
            continue
        persona_id = str(row.get("persona_id") or "")
        if persona_id and experience_has_login_blocker(row):
            current_login[persona_id] = True
    if not current_login:
        return []
    to_adjust: list[dict[str, Any]] = []
    for persona in personas:
        persona_id = str(persona.get("id") or "")
        if persona_id not in current_login:
            continue
        existing = normalize_persona_initial_state(persona.get("initial_state"))
        if existing and existing.get("source") == "manual" and existing.get("test_account"):
            continue
        prior = persona_login_blocker_history_count(state, persona_id)
        if existing and existing.get("test_account") and prior < 1:
            continue
        if not existing or not existing.get("test_account") or prior >= 1:
            to_adjust.append(persona)
    if not to_adjust:
        return []
    suggestions = suggest_persona_initial_states_via_orchestrator(
        state,
        to_adjust,
        reason="虚拟用户重复在登录/注册环节受阻，需要配置测试账号初始状态",
    )
    changed: list[str] = []
    by_id = {str(item.get("id") or ""): item for item in personas}
    for persona in to_adjust:
        persona_id = str(persona.get("id") or "")
        suggested = suggestions.get(persona_id) or {}
        initial = build_persona_initial_state(
            persona,
            test_account=suggested.get("test_account") or derive_test_account_username(persona),
            auth_notes=suggested.get("auth_notes") or "",
            reason="登录/注册卡点重复出现，已自动配置测试账号初始状态",
            source="orchestrator",
        )
        if not initial:
            continue
        merged = dict(by_id.get(persona_id) or persona)
        merged["initial_state"] = initial
        by_id[persona_id] = finalize_persona(merged, index=0)
        changed.append(persona_id)
    if changed:
        state["personas"] = [
            by_id.get(str(item.get("id") or ""), item)
            for item in personas
        ]
        save_state(state)
    return changed

PERSONA_MUTATION_OP_SCHEMA = obj(
    {
        "op": {"type": "string", "enum": ["add", "update", "remove"]},
        "persona_id": STR,
        "persona": PERSONA_PATCH_SCHEMA,
    },
    ["op"],
)

PERSONA_UPDATE_SCHEMA = obj(
    {
        "apply": BOOL,
        "summary": STR,
        "operations": {"type": "array", "items": PERSONA_MUTATION_OP_SCHEMA},
    },
    ["apply", "summary", "operations"],
)

_PERSONA_UPDATE_INTENT_RE = re.compile(
    r"虚拟用户|体验(?:者|画像)|目标用户|用户画像|受众|persona|"
    r"(?:新增|增加|添加|删除|移除|更新|调整|修改).{0,12}(?:用户|画像|体验者)|"
    r"(?:add|remove|update|delete).{0,12}(?:persona|user profile)",
    re.I,
)


def persona_public_payload(persona: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in persona.items() if not str(key).startswith("_")}


_PERSONA_MOBILE_DEVICE_RE = re.compile(
    r"手机|行動|移动|iphone|android|ipad|\bmobile\b|\bphone\b|\bh5\b",
    re.IGNORECASE,
)
_PERSONA_DESKTOP_DEVICE_RE = re.compile(
    r"电脑|電腦|台式|笔记本|windows|\bmac\b|desktop|\bpc\b|laptop",
    re.IGNORECASE,
)


def infer_persona_trial_surface(persona: dict[str, Any]) -> str:
    """Map a virtual user onto desktop_web or mobile_web without inventing a new person."""

    existing = str(persona.get("trial_surface") or persona.get("experience_surface") or "").strip()
    if existing in {"desktop_web", "mobile_web"}:
        return existing
    parts = [
        str(persona.get("device") or ""),
        str(persona.get("constraints") or ""),
        str(persona.get("habits") or ""),
    ]
    device_i18n = persona.get("device_i18n")
    if isinstance(device_i18n, dict):
        parts.extend(str(value or "") for value in device_i18n.values())
    blob = " ".join(parts)
    mobile = bool(_PERSONA_MOBILE_DEVICE_RE.search(blob))
    desktop = bool(_PERSONA_DESKTOP_DEVICE_RE.search(blob))
    if mobile and not desktop:
        return "mobile_web"
    if desktop and not mobile:
        return "desktop_web"
    return ""


def assign_persona_trial_surfaces(personas: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Keep some virtual users on desktop web and some on phone web."""

    rows = [dict(item) for item in personas if isinstance(item, dict)]
    assigned = [infer_persona_trial_surface(item) for item in rows]
    unset = [index for index, surface in enumerate(assigned) if not surface]
    for offset, index in enumerate(unset):
        assigned[index] = "desktop_web" if offset % 2 == 0 else "mobile_web"
    if len(rows) >= 2 and len({item for item in assigned if item}) < 2:
        assigned[-1] = "mobile_web" if assigned[0] == "desktop_web" else "desktop_web"
    for persona, surface in zip(rows, assigned):
        persona["trial_surface"] = surface or "desktop_web"
    return rows


def finalize_persona(raw: dict[str, Any], *, index: int = 0) -> dict[str, Any]:
    persona = dict(raw)
    persona["id"] = re.sub(r"[^a-zA-Z0-9_-]", "-", str(persona.get("id") or f"p{index:02d}"))[:40] or f"p{index:02d}"
    script: list[dict[str, str]] = []
    for step_index, raw_step in enumerate(persona.get("task_script") or [], 1):
        if isinstance(raw_step, dict):
            action = str(raw_step.get("action") or raw_step.get("task") or raw_step.get("description") or "").strip()
        else:
            action = str(raw_step or "").strip()
        if action:
            script.append({"id": f"s{step_index:02d}", "action": action})
    persona["task_script"] = script
    initial = normalize_persona_initial_state(persona.get("initial_state"))
    if initial:
        persona["initial_state"] = initial
    else:
        persona.pop("initial_state", None)
    normalize_optional_persona_evidence(persona)
    public = persona_public_payload(persona)
    persona_hash = hashlib.sha256(json.dumps(public, ensure_ascii=False, sort_keys=True).encode()).hexdigest()[:10]
    persona["_session_key"] = f"experience:{persona['id']}:{persona_hash}"
    return persona


