def _merge_operations_skill_update(skill: dict[str, Any], updated: Any, *, now: str) -> bool:
    if updated is None:
        return False
    if isinstance(updated, str):
        text = updated.strip()[:6000]
        if not text:
            return False
        skill["instructions"] = text
        skill["is_default"] = False
        skill["revision"] = max(1, int(skill.get("revision") or 1)) + 1
        skill["updated_at"] = now
        return True
    if not isinstance(updated, dict):
        return False
    changed = False
    for key in ("name", "summary", "instructions", "config_mode"):
        value = updated.get(key)
        if isinstance(value, str) and value.strip():
            skill[key] = value.strip()[:6000 if key == "instructions" else 120]
            changed = True
    if isinstance(updated.get("data_sources"), list):
        skill["data_sources"] = updated.get("data_sources")
        skill["config_mode"] = "advanced"
        changed = True
    if isinstance(updated.get("campaign_items"), list):
        skill["campaign_items"] = updated.get("campaign_items")
        skill["config_mode"] = "advanced"
        changed = True
    if isinstance(updated.get("missing_fields"), list):
        skill["missing_fields"] = updated.get("missing_fields")
        changed = True
    if not changed:
        return False
    skill["is_default"] = False
    skill["revision"] = max(1, int(skill.get("revision") or 1)) + 1
    skill["updated_at"] = now
    return True


def process_one_operations_request(state: dict[str, Any]) -> bool:
    """Process one queued release/operations conversation turn."""

    model, storage = _read_operations_model(state)
    if storage == "none":
        return False
    request = next(
        (
            row for row in model.get("agent_requests") or []
            if isinstance(row, dict) and str(row.get("status") or "") == "queued"
        ),
        None,
    )
    if request is None:
        return False
    request_id = str(request.get("id") or "")
    kind = str(request.get("kind") or "chat")
    user_text = str(request.get("text") or "").strip()
    if user_text:
        maybe_apply_persona_updates_from_message(state, user_text, source="operations_chat")
    if kind == "deploy":
        text = str(request.get("text") or "").strip() or (
            "请严格按照当前上线 Skill 检查并执行上线；涉及凭据、付费、公开发布或其他高风险操作时先向用户确认。"
        )
        inbox = run_dir(state["run_id"]) / "inbox"
        inbox.mkdir(parents=True, exist_ok=True)
        message_id = "web-in-" + uuid.uuid4().hex
        now = utcnow()
        filename = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%S%fZ") + f"-{uuid.uuid4().hex}.json"
        atomic_json(
            inbox / filename,
            {
                "message_id": message_id,
                "body": text,
                "text": text,
                "channel": "main",
                "pending_id": "",
                "matched_pending_id": "",
                "attachment_ids": [],
                "attachments": [],
                "created_at": now,
            },
        )
        request.update({"status": "completed", "updated_at": now, "error": ""})
        agent = _operations_agent_state(model, state)
        agent.update({
            "status": "completed",
            "current_request_id": request_id,
            "current_action": "",
            "updated_at": now,
            "last_error": "",
        })
        _write_operations_model(state, model, storage)
        event(state, "operations_deploy_rerouted_to_developer", request_id=request_id)
        return True
    now = utcnow()
    request.update({"status": "running", "updated_at": now, "error": ""})
    agent = _operations_agent_state(model, state)
    agent.update({
        "status": "running",
        "current_request_id": request_id,
        "current_action": "Replying to the user",
        "updated_at": now,
        "last_error": "",
    })
    _write_operations_model(state, model, storage)
    prompt = prompt_json(
        "You are the operations agent for this application. Reply concisely in the user's language. "
        "You manage two separate operational domains: (1) data statistics — in-app safe event tracking, "
        "authorized analytics sources, and aggregate dashboard metrics; (2) traffic acquisition — ad platforms, "
        "delivery method, budget, schedule, and trigger conditions. Use the skills below for each domain. "
        "Release/deploy work belongs to the developer agent; do not execute deployment here. "
        "Do not claim success without evidence. Before credentials, payment, public release, ad spend, "
        "destructive changes, or system-level changes, explain the exact action and ask for explicit confirmation. "
        "Update analytics_skill or traffic_skill only when the user's request clearly changes that domain; "
        "otherwise return null. Structured skill objects may include summary, config_mode, data_sources, "
        "campaign_items, and missing_fields. When required information such as website URLs or API endpoints "
        "is missing, ask one focused follow-up question and populate missing_fields so the UI can guide the user. "
        "When the user asks to add, remove, or update virtual users / target audience personas, include persona_operations "
        "with add/update/remove entries. Only change personas when the user clearly requests audience or persona changes.",
        {
            "request": {"kind": kind, "text": str(request.get("text") or "")[:4000]},
            "analytics_skill": (model.get("analytics_skill") or model.get("operations_skill") or {}),
            "traffic_skill": (model.get("traffic_skill") or {}),
            "traffic_state": model.get("traffic_state") or {},
            "public_environment": model.get("public_environment") or {},
            "available_metrics": {
                key: value for key, value in (model.get("metrics") or {}).items()
                if isinstance(value, dict) and value.get("status") == "available"
            },
        },
    )
    try:
        result = call_claude(
            state,
            "operations",
            prompt,
            OPERATIONS_AGENT_REPLY_SCHEMA,
            writable=kind == "deploy",
        )
        model, storage = _read_operations_model(state)
        request = next(
            (row for row in model.get("agent_requests") or [] if isinstance(row, dict) and row.get("id") == request_id),
            None,
        )
        if request is None:
            return True
        now = utcnow()
        request.update({"status": "completed", "updated_at": now, "error": ""})
        reply = str(result.get("reply") or "").strip()[:6000] or "本次运营请求已处理。"
        request_text = lifecycle_safe_text(request.get("text"), "", limit=280)
        model.setdefault("messages", []).append({
            "id": "opmsg-" + uuid.uuid4().hex,
            "actor": "agent",
            "body": reply,
            "created_at": now,
            "request_id": request_id,
            "reply_to": {
                "message_id": request_id,
                "body": request_text,
            },
        })
        model["messages"] = model["messages"][-160:]
        for key in ("analytics_skill", "traffic_skill", "operations_skill"):
            updated = result.get(key)
            if updated is None:
                continue
            if isinstance(updated, str) and not updated.strip():
                continue
            if isinstance(updated, dict) and not updated:
                continue
            target_key = "analytics_skill" if key == "operations_skill" else key
            skill = model.setdefault(target_key, {})
            if not isinstance(skill, dict):
                skill = {}
                model[target_key] = skill
            _merge_operations_skill_update(skill, updated, now=now)
        if isinstance(model.get("analytics_skill"), dict):
            model["operations_skill"] = json.loads(json.dumps(model["analytics_skill"], ensure_ascii=False))
        persona_operations = result.get("persona_operations")
        if isinstance(persona_operations, list) and persona_operations:
            try:
                apply_persona_mutations(state, persona_operations, source="operations_agent")
            except WorkflowError as exc:
                reply = f"{reply}\n\n（虚拟用户调整未生效：{str(exc)[:200]}）"
        traffic_state = result.get("traffic_state")
        if isinstance(traffic_state, dict) and traffic_state:
            model["traffic_state"] = {
                **(model.get("traffic_state") if isinstance(model.get("traffic_state"), dict) else {}),
                **traffic_state,
                "updated_at": now,
            }
        session = state.get("sessions", {}).get("operations", {})
        agent = _operations_agent_state(model, state)
        agent.update({
            "session_id": str(session.get("id") or ""),
            "status": "completed",
            "current_request_id": request_id,
            "current_action": "",
            "updated_at": now,
            "last_error": "",
        })
        _write_operations_model(state, model, storage)
        event(state, "operations_request_completed", request_id=request_id, request_kind=kind)
    except Exception as exc:
        model, storage = _read_operations_model(state)
        request = next(
            (row for row in model.get("agent_requests") or [] if isinstance(row, dict) and row.get("id") == request_id),
            None,
        )
        if request is not None:
            reason = operations_public_worker_retry_reason(str(exc))
            now = utcnow()
            request.update({"status": "error", "updated_at": now, "error": reason[:500]})
            agent = _operations_agent_state(model, state)
            agent.update({
                "status": "error",
                "current_request_id": request_id,
                "current_action": "",
                "updated_at": now,
                "last_error": reason[:500],
            })
            model.setdefault("messages", []).append({
                "id": "opmsg-" + uuid.uuid4().hex,
                "actor": "agent",
                "body": f"暂时无法完成：{reason}",
                "created_at": now,
                "request_id": request_id,
            })
            _write_operations_model(state, model, storage)
        event(state, "operations_request_failed", request_id=request_id, request_kind=kind, error_type=type(exc).__name__)
    return True


def public_worker_retry_reason(error: str, state: dict[str, Any] | None = None) -> str:
    """Return a short, non-technical reason for a recoverable worker retry."""

    normalized = str(error or "").casefold()
    if any(
        marker in normalized
        for marker in (
            "not logged in",
            "please run /login",
            "authentication required",
            "authentication failed",
            "unauthorized coding agent",
        )
    ):
        return "研发服务认证暂不可用"
    if (
        "weekly limit" in normalized
        or "usage limit" in normalized
        or "resetsat" in normalized
        or "额度已用完" in normalized
    ):
        return "Claude Code 本周期额度已用完"
    if "required property" in normalized or "structured output" in normalized:
        return "研发结果格式需要自动整理"
    if "experience twin" in normalized and "changelog" in normalized:
        return "体验变更说明需要自动精简"
    if any(
        marker in normalized
        for marker in (
            "request body too large",
            "request too large",
            "payload too large",
            "context length",
            "context window",
            "contextwindowexceedederror",
            "prompt is too long",
            "invalid json data",
            "failed to deserialize the json body",
            "responseinput",
            "json_parse_error",
            "请求体太大",
            "请求体太长",
            "请求量太大",
            "上下文太长",
            "������̫����",
        )
    ):
        return "发送给研发智能体的上下文过大"
    if "rate limit" in normalized or "too many requests" in normalized or "请求过于频繁" in normalized:
        return "研发服务当前请求较多"
    if "command line too long" in normalized or "命令行太长" in normalized:
        return "Claude Code 启动参数过长"
    if "timeout" in normalized or "超时" in normalized:
        return "研发服务本次响应超时"
    if any(
        marker in normalized
        for marker in (
            "maximum budget",
            "error_max_budget_usd",
            "budget_exhausted",
            "max budget",
        )
    ):
        budget = None
        if isinstance(state, dict):
            with contextlib.suppress(TypeError, ValueError):
                budget = float(state.get("max_budget_usd") or 0) or None
        if budget:
            return f"Claude Code 单次调用预算已用尽（${budget:g}）"
        return "Claude Code 单次调用预算已用尽"
    return "后台研发步骤暂时失败"


def operations_public_worker_retry_reason(error: str) -> str:
    """Map worker failures for operations chat/deploy turns to user-facing copy."""

    mapped = public_worker_retry_reason(error)
    operations_overrides = {
        "后台研发步骤暂时失败": "运营智能体本次处理失败",
        "发送给研发智能体的上下文过大": "运营对话上下文过大",
        "研发服务当前请求较多": "运营服务当前请求较多",
        "研发服务本次响应超时": "运营智能体本次响应超时",
        "研发结果格式需要自动整理": "运营结果格式需要自动整理",
    }
    return operations_overrides.get(mapped, mapped)


def worker_retry_reason_code(error: str, state: dict[str, Any] | None = None) -> str:
    reason = public_worker_retry_reason(error, state)
    if "额度" in reason or "请求限制" in reason:
        return "coding_agent_quota_exhausted"
    if "上下文过大" in reason:
        return "context_too_large"
    if "认证暂不可用" in reason:
        return "provider_auth_unavailable"
    if "请求较多" in reason:
        return "rate_limited"
    if "启动参数过长" in reason:
        return "command_line_too_long"
    if "超时" in reason:
        return "timeout"
    if "预算已用尽" in reason:
        return "budget_exhausted"
    if "格式" in reason:
        return "invalid_result_format"
    if "变更说明" in reason:
        return "invalid_experience_summary"
    return "background_step_failed"


def worker_error_signature(error: str) -> str:
    """Group equivalent failures while ignoring volatile ids and numbers."""

    normalized = str(error or "").casefold()
    normalized = re.sub(r"[0-9a-f]{8}-[0-9a-f-]{27,}", "<id>", normalized)
    normalized = re.sub(r"\b\d+(?:\.\d+)?\b", "<n>", normalized)
    normalized = re.sub(r"\s+", " ", normalized).strip()
    return hashlib.sha256(normalized.encode("utf-8", errors="replace")).hexdigest()[:20]


def developer_session_handoff(state: dict[str, Any], error: str) -> dict[str, Any]:
    return build_developer_session_handoff(state, error)


def processing_developer_reply_failure(state: dict[str, Any]) -> dict[str, Any] | None:
    """Return the queue head only when its read-only developer turn failed."""

    for item in state.get("developer_message_queue") or []:
        if not isinstance(item, dict) or item.get("user_message_state") == "replied":
            continue
        if item.get("user_message_state") != "processing":
            return None
        if item.get("reply_failure") or item.get("reply_attempt_in_progress"):
            return item
        return None
    return None


def reconcile_interrupted_developer_reply(state: dict[str, Any]) -> bool:
    """Clear stale in-flight flags so a restarted worker can resume the queue head."""

    changed = False
    for item in state.get("developer_message_queue") or []:
        if not isinstance(item, dict):
            continue
        if item.get("user_message_state") != "processing":
            continue
        has_draft = isinstance(item.get("reply_draft"), dict) and bool(item.get("reply_draft"))
        handling_status = str(item.get("handling_status") or "")
        if item.get("reply_attempt_in_progress"):
            item["reply_attempt_in_progress"] = False
            changed = True
        # A classified message without a draft was interrupted mid-reply; allow the
        # next scheduler turn to finish the lightweight developer acknowledgement.
        if handling_status and not has_draft and not item.get("reply_failure"):
            item["reply_attempt_in_progress"] = False
            changed = True
    return changed


def reconcile_completed_experience_feedback(state: dict[str, Any]) -> bool:
    """Restore the DEVELOP transition after an interrupted experience commit.

    The experience gate persists its durable queue/results and feedback before
    the next developer turn.  A container/worker handoff in that narrow window
    can leave the older ``EXPERIENCE`` phase behind even though the queue is
    complete and actionable feedback already exists.  Re-running personas in
    that state loses time and can hide the developer response indefinitely.
    Treat this combination as a phase-commit journal and finish the one-way
    transition.  An active/partial batch is never modified.
    """

    if str(state.get("phase") or "").strip().upper() != "EXPERIENCE":
        return False
    feedback = [row for row in state.get("feedback") or [] if isinstance(row, dict)]
    if not feedback or isinstance(state.get("experience_batch"), dict):
        return False
    active_queue = [
        row for row in state.get("internal_test_queue") or [] if isinstance(row, dict)
    ]
    if active_queue:
        return False
    completed_queue = [
        row
        for row in state.get("last_internal_test_queue") or []
        if isinstance(row, dict)
    ]
    if not completed_queue or any(
        str(row.get("status") or "").strip().lower() != "completed"
        for row in completed_queue
    ):
        return False
    feedback_sources = sorted(
        {
            str(row.get("source") or "experience").strip() or "experience"
            for row in feedback
        }
    )
    state.pop("developmental_experience", None)
    state.pop("experience_mode", None)
    state["phase"] = "DEVELOP"
    state["status"] = "running"
    set_public_work_summary(
        state,
        kind="developing",
        current=app_i18n.pair(
            "试用与意图复核已完成，正在恢复研发智能体处理反馈",
            "Experience and intent review completed; restoring the developer agent to address feedback",
        ),
        next_step=app_i18n.pair(
            "研发完成修复后会再次交给测试智能体与虚拟用户试用",
            "After the fix, the test agent and virtual users will try the updated build again",
        ),
    )
    event(
        state,
        "completed_experience_feedback_reconciled",
        feedback_sources=feedback_sources,
        completed_personas=len(completed_queue),
        candidate_id=str(state.get("experience_candidate") or ""),
    )
    return True


def first_developer_delivery_complete(state: dict[str, Any]) -> bool:
    """True after the developer agent has published a structured first build."""

    last = state.get("last_developer") if isinstance(state.get("last_developer"), dict) else {}
    if last.get("ready_for_review") is True:
        return True
    if str(last.get("summary") or "").strip():
        return True
    changes = last.get("changes")
    if isinstance(changes, list) and any(str(item or "").strip() for item in changes):
        return True
    if str(last.get("experience_entry") or "").strip():
        return True
    handoff = state.get("agent_feedback_handoff")
    if isinstance(handoff, dict) and str(handoff.get("message_id") or "").strip():
        return True
    handoffs = state.get("agent_feedback_handoffs")
    if isinstance(handoffs, dict) and any(
        isinstance(row, dict) and str(row.get("message_id") or "").strip()
        for row in handoffs.values()
    ):
        return True
    return False


def initial_build_attention_state(state: dict[str, Any]) -> dict[str, Any] | None:
    """Timeout card for a failed first developer build."""

    if first_developer_delivery_complete(state):
        return None
    if str(state.get("phase") or "").upper() in {"DELIVERED", "STOPPED"}:
        return None
    last_error = str(state.get("last_error") or state.get("last_transient_error") or "")
    status = str(state.get("status") or "")
    retrying = status == "retrying_error" or bool(state.get("worker_retry_reason_code"))
    failed = (
        retrying
        or bool(last_error)
        or status in {"paused_error", "paused_safety", "failed", "error"}
    )
    if not failed:
        return None
    if str(state.get("initial_build_attention_acked_at") or "").strip():
        return None
    reason_code = str(
        state.get("worker_retry_reason_code")
        or worker_retry_reason_code(last_error, state)
        or "timeout"
    )[:80]
    return {
        "active": True,
        "reason_code": reason_code,
        "retryable": True,
    }


def mark_initial_build_retry_requested(state: dict[str, Any]) -> None:
    """Hide the timeout card and wake a sleeping first-build retry."""

    state["initial_build_attention_acked_at"] = utcnow()
    state["worker_retry_after"] = 0
    run_id = str(state.get("run_id") or "")
    if not run_id:
        return
    path = run_dir(run_id) / "retry_now"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("1", encoding="utf-8")


def consume_worker_retry_now(run_id: str) -> bool:
    path = run_dir(str(run_id or "")) / "retry_now"
    if not path.exists():
        return False
    with contextlib.suppress(OSError):
        path.unlink()
    return True


def _mark_initial_build_attention(state: dict[str, Any]) -> None:
    if first_developer_delivery_complete(state):
        return
    state.pop("initial_build_attention_acked_at", None)
    state["initial_build_attention"] = True


def prepare_worker_retry(state: dict[str, Any], error_text: str) -> tuple[int, bool]:
    """Record one failure and rotate a repeatedly failing developer session."""

    signature = worker_error_signature(error_text)
    previous_signature = str(state.get("worker_retry_fingerprint") or "")
    if not previous_signature and state.get("last_error"):
        previous_signature = worker_error_signature(str(state.get("last_error") or ""))
    previous_same_error_count = int(
        state.get("worker_retry_same_error_count", state.get("worker_retry_count", 0))
    )
    same_error_count = previous_same_error_count + 1 if previous_signature == signature else 1
    state["worker_retry_count"] = int(state.get("worker_retry_count", 0)) + 1
    state["worker_retry_fingerprint"] = signature
    state["worker_retry_same_error_count"] = same_error_count
    state["worker_retry_reason"] = public_worker_retry_reason(error_text, state)
    state["worker_retry_reason_code"] = worker_retry_reason_code(error_text, state)
    state["worker_retry_session_rotated"] = False
    rotated = False
    reconcile_interrupted_developer_reply(state)
    failed_reply = processing_developer_reply_failure(state)
    legacy_developer_failure = (
        str(state.get("phase") or "").upper() == "DEVELOP"
        and str(state.get("coding_agent") or "claude") == "claude"
        and "claude code developer" in error_text.casefold()
    )
    quota_exhausted = state["worker_retry_reason_code"] == "coding_agent_quota_exhausted"
    budget_exhausted = state["worker_retry_reason_code"] == "budget_exhausted"
    provider_auth_unavailable = state["worker_retry_reason_code"] == "provider_auth_unavailable"
    triage_result_error = any(
        marker in str(error_text or "")
        for marker in (
            "体验反馈分流不完整",
            "体验反馈 scope 与原始 Computer Use 问题不一致",
        )
    )
    repeated_development_failure = (
        str(state.get("phase") or "").upper() == "DEVELOP"
        and same_error_count >= 2
        and state["worker_retry_reason_code"] == "background_step_failed"
        and not triage_result_error
    )
    if (
        (
            repeated_development_failure
            or (
                same_error_count >= 3
                and (legacy_developer_failure or failed_reply is not None or triage_result_error)
            )
        )
        and not quota_exhausted
        and not provider_auth_unavailable
    ):
        state["developer_session_handoff"] = build_developer_session_handoff(state, error_text)
        rotate_session(state, "developer", reason=f"context_recovery:{state['worker_retry_reason_code']}")
        reset_stuck_developer_queue(state)
        if failed_reply is not None:
            failed_reply["reply_attempt_in_progress"] = False
            failed_reply["reply_failure"] = False
            failed_reply["reply_failure_error"] = ""
            failed_reply["reply_session_rotated_at"] = utcnow()
        state["worker_retry_same_error_count"] = 0
        state["worker_retry_session_rotated"] = True
        rotated = True
        set_public_work_summary(
            state,
            kind="recovering",
            current="研发上下文过大或格式不兼容，已压缩交接并重建会话",
            next_step="将使用字符串化/摘要上下文继续当前任务",
        )
    retry_exponent = max(0, int(state.get("worker_retry_same_error_count", 0)) - 1)
    delay = min(900, max(15, int(state["poll_seconds"])) * (2 ** min(retry_exponent, 4)))
    if quota_exhausted:
        reset_match = re.search(r'"?resetsAt"?\s*[:=]\s*"?(\d{10,13})', str(error_text or ""), re.IGNORECASE)
        if reset_match:
            reset_epoch = int(reset_match.group(1))
            if reset_epoch > 100_000_000_000:
                reset_epoch //= 1000
            delay = max(60, reset_epoch - int(time.time()))
            state["worker_retry_quota_resets_at"] = reset_epoch
        else:
            delay = max(delay, 900)
    if provider_auth_unavailable:
        delay = max(delay, 120)
    if budget_exhausted:
        state["status"] = "retrying_error"
        state["last_error"] = error_text
        _mark_initial_build_attention(state)
        set_public_work_summary(
            state,
            kind="retrying",
            current="研发服务正在等待可用资源，当前进度和消息均已保存",
            next_step="资源可用后会自动继续，无需手动恢复",
        )
        return delay, rotated
    try:
        circuit_limit = max(
            2,
            int(os.environ.get("WF_WORKER_RECOVERY_CIRCUIT", WORKER_RECOVERY_CIRCUIT_DEFAULT)),
        )
    except (TypeError, ValueError):
        circuit_limit = WORKER_RECOVERY_CIRCUIT_DEFAULT
    if int(state.get("worker_retry_count") or 0) >= circuit_limit:
        reason_code = str(state.get("worker_retry_reason_code") or "background_step_failed")
        state["status"] = "retrying_error"
        state["last_error"] = error_text
        _mark_initial_build_attention(state)
        state["internal_recovery_diagnostic"] = {
            "reason_code": f"worker_retry_circuit:{reason_code}",
            "recoverable": True,
            "phase": str(state.get("phase") or ""),
            "attempts": int(state.get("worker_retry_count") or 0),
            "last_error": error_text[:1_000],
            "created_at": utcnow(),
            "resume_action": "rotate_phase_session_and_retry",
        }
        state.pop("recovery_required", None)
        state["worker_retry_count"] = 0
        state["worker_retry_same_error_count"] = 0
        _rotate_phase_sessions_for_recovery(state)
        set_public_work_summary(
            state,
            kind="retrying",
            current="研发服务正在重新连接，当前进度和消息均已保存",
            next_step="系统会自动继续处理，无需手动恢复",
        )
        event(
            state,
            "worker_recovery_required",
            reason_code=reason_code,
            attempts=int(state.get("worker_retry_count") or 0),
            circuit_limit=circuit_limit,
        )
        return delay, rotated
    state["worker_retry_after"] = time.time() + delay
    state["status"] = "retrying_error"
    state["last_error"] = error_text
    _mark_initial_build_attention(state)
    return delay, rotated


def clear_worker_recovery(state: dict[str, Any]) -> None:
    keys = (
        "worker_retry_count",
        "worker_retry_after",
        "worker_retry_fingerprint",
        "worker_retry_same_error_count",
        "worker_retry_reason",
        "worker_retry_reason_code",
        "worker_retry_session_rotated",
        "worker_retry_quota_resets_at",
        "last_transient_error",
        "last_error",
    )
    recovered = any(k in state for k in keys)
    for key in keys:
        state.pop(key, None)
    if recovered:
        summary = state.get("public_work_summary")
        if isinstance(summary, dict) and str(summary.get("kind") or "") == "retrying":
            set_public_work_summary(
                state,
                kind="developing",
                current="研发智能体已从错误中恢复，继续处理当前任务",
                next_step="排队消息将按顺序处理",
            )
        event(state, "worker_recovered")


def begin_worker_retry_attempt(state: dict[str, Any]) -> None:
    """Clear stale UI timing without erasing the consecutive-failure history."""

    state.pop("worker_retry_after", None)
    consume_worker_retry_now(str(state.get("run_id") or ""))
    if state.get("last_error"):
        state["last_transient_error"] = str(state.pop("last_error"))[:1_000]
    state["status"] = live_status(str(state.get("phase") or ""))


def wait_for_stop(
    stop: Path,
    seconds: float,
    *,
    run_id: str = "",
    worker_generation: int | None = None,
) -> bool:
    def requested() -> bool:
        return bool(
            (stop_request_is_current(run_id, stop) if run_id else stop.exists())
            or (
                bool(run_id)
                and worker_generation is not None
                and newer_resume_handoff_pending(run_id, worker_generation)
            )
            or (bool(run_id) and (run_dir(run_id) / "retry_now").exists())
        )

    deadline = time.time() + max(0, seconds)
    while time.time() < deadline:
        if requested():
            return True
        time.sleep(min(2, max(0, deadline - time.time())))
    return requested()


def classify_safety_hold(exc: BaseException, state: dict[str, Any]) -> dict[str, Any]:
    """Return a stable, participant-safe recovery contract for a fatal error."""

    detail = f"{type(exc).__name__}: {exc}"
    folded = detail.casefold()
    reason_code = "workflow_integrity_violation"
    recoverable = False
    resume_action = "operator_review_required"
    if "exhausted its frozen attempt budget" in folded:
        reason_code = "release_evaluator_attempt_budget_exhausted"
        # Pre-v3 releases could hard-stop on a frozen attempt budget. Current
        # semantics have no budget; treat residual messages as recoverable so
        # migrate_state / resume can clear them and continue the loop.
        recoverable = True
        resume_action = "clear_obsolete_attempt_budget_and_rotate_reviewer"
    elif "evaluator model does not match" in folded:
        reason_code = "release_evaluator_model_mismatch"
        recoverable = True
        resume_action = "align_frozen_evaluator_model_and_rotate_reviewer"
    elif "unknown phase" in folded or "未知阶段" in detail:
        reason_code = "unknown_workflow_phase"
    elif "guardrail" in folded or "护栏" in detail:
        reason_code = "guardrail_integrity_violation"
    elif "read-only" in folded or "只读智能体" in detail:
        reason_code = "readonly_candidate_mutation"
    return {
        "reason_code": reason_code,
        "recoverable": recoverable,
        "phase": str(state.get("phase") or ""),
        "last_error": detail[:1_000],
        "created_at": utcnow(),
        "resume_action": resume_action,
        "candidate_id": str(
            (state.get("candidate_readiness") or {}).get("candidate_id")
            or (state.get("validation") or {}).get("candidate_id")
            or ""
        )[:96],
        "attempt_key": str(state.get("release_evaluator_active_attempt_key") or "")[:240],
    }


def _rotate_phase_sessions_for_recovery(state: dict[str, Any]) -> list[str]:
    sessions = state.setdefault("sessions", {})
    if not isinstance(sessions, dict):
        sessions = state["sessions"] = {}
    phase = str(state.get("phase") or "").upper()
    prefixes = (
        ("reviewer",) if phase == "REVIEW"
        else ("developer",) if phase in {"PLAN", "DEVELOP"}
        else ("experience:", "internal_test_analyst") if phase == "EXPERIENCE"
        else ()
    )
    removed: list[str] = []
    for key in list(sessions):
        if any(key == prefix or key.startswith(prefix) for prefix in prefixes):
            sessions.pop(key, None)
            removed.append(key)
    return removed


def prepare_recovery_resume(state: dict[str, Any]) -> None:
    """Make a recoverable hold runnable without weakening integrity failures."""

    hold = state.get("safety_hold") if isinstance(state.get("safety_hold"), dict) else {}
    recovery = (
        state.get("recovery_required")
        if isinstance(state.get("recovery_required"), dict)
        else {}
    )
    active = hold or recovery
    if not active:
        return
    if active.get("recoverable") is not True:
        raise WorkflowError(
            "该安全保护涉及候选版本或护栏完整性，必须先由管理员检查，不能直接恢复"
        )
    reason_code = str(active.get("reason_code") or "")
    if reason_code == "release_evaluator_attempt_budget_exhausted":
        # Obsolete frozen budgets are cleared unconditionally under v3+.
        attempts = state.get("release_evaluator_attempts")
        if not isinstance(attempts, dict):
            attempts = state["release_evaluator_attempts"] = {}
        attempt_key = str(active.get("attempt_key") or "")
        if attempt_key:
            attempts.pop(attempt_key, None)
        else:
            attempts.clear()
        state["release_evaluator_attempt_semantics_version"] = (
            RELEASE_EVALUATOR_ATTEMPT_SEMANTICS_VERSION
        )
    elif reason_code == "release_evaluator_model_mismatch":
        contract = study_evaluator_contract(state)
        overrides = state.setdefault("role_model_overrides", {})
        if not isinstance(overrides, dict):
            overrides = state["role_model_overrides"] = {}
        overrides["reviewer"] = str(contract.get("model") or "")
    removed = _rotate_phase_sessions_for_recovery(state)
    history = [
        item for item in state.get("recovery_history") or [] if isinstance(item, dict)
    ]
    history.append(
        {
            **active,
            "resumed_at": utcnow(),
            "rotated_sessions": removed,
        }
    )
    state["recovery_history"] = history[-30:]
    state.pop("safety_hold", None)
    state.pop("recovery_required", None)
    clear_worker_recovery(state)
    state["status"] = "paused"
    event(state, "workflow_recovery_resumed", reason_code=reason_code, rotated_sessions=removed)
    save_state(state)


def infer_stopped_resume_phase(state: dict[str, Any]) -> str:
    """Recover the safest durable phase when an old stop lost its phase field.

    Modern stops persist ``stopped_from_phase``.  Legacy and partially-written
    stop records did not, and defaulting those mature runs to PLAN can replay
    completed development work.  Candidate readiness is monotonic durable
    evidence, so prefer REVIEW for candidates already under evaluation and
    DELIVER for candidates that have completed independent validation.
    """

    explicit = str(state.get("stopped_from_phase") or "").strip().upper()
    if explicit in {"PLAN", "DEVELOP", "REVIEW", "EXPERIENCE", "DELIVER", "WAIT_USER"}:
        return explicit
    readiness = state.get("candidate_readiness")
    readiness = readiness if isinstance(readiness, dict) else {}
    stage = str(readiness.get("stage") or "developing").strip()
    if stage in {"owner_review_ready", "published"}:
        return "DELIVER"
    if stage == "trial_ready":
        return "EXPERIENCE"
    if stage in {"dev_ready", "evaluating"}:
        return "REVIEW"
    validation = state.get("validation")
    if isinstance(validation, dict) and validation.get("passed") is True:
        return "EXPERIENCE"
    tasks = [row for row in state.get("tasks") or [] if isinstance(row, dict)]
    if tasks and all(task_is_implemented(row) for row in tasks):
        return "REVIEW"
    if state.get("last_developer") or state.get("experience_twin"):
        return "DEVELOP"
    return "PLAN"


def run_workflow(
    run_id: str,
    *,
    once: bool = False,
    control_generation: int = 0,
    launch_id: str = "",
    client_request_id: str = "",
    spawn_attempt_id: str = "",
) -> None:
    with RunLock(run_id):
        # A detached parent holds WorkerLaunchLock until it has published this
        # child's PID identity.  Taking the same lock here prevents the child
        # from advancing state during that handoff; direct foreground launches
        # use the identical contract.
        with WorkerLaunchLock(run_id):
            state = load_state(run_id)
            durable_control = (
                state.get("worker_control")
                if isinstance(state.get("worker_control"), dict)
                else {}
            )
            if not control_generation and int(durable_control.get("generation") or 0) > 0:
                # An initial detached child whose parent died before publishing
                # its PID loses to any later durable Stop/Resume generation.
                # It must exit before adopting state or doing workflow work.
                return
            launch_request = state.get("resume_request")
            launch_request = launch_request if isinstance(launch_request, dict) else {}
            if control_generation and (
                not worker_control_matches(
                    state,
                    generation=control_generation,
                    launch_id=launch_id,
                )
                or str(launch_request.get("client_request_id") or "")
                != str(client_request_id)
                or str(launch_request.get("status") or "") not in {"accepted", "launching"}
                or (
                    bool(spawn_attempt_id)
                    and (
                        str(launch_request.get("spawn_attempt_id") or "")
                        != str(spawn_attempt_id)
                        or str(
                            (state.get("worker_control") or {}).get("spawn_attempt_id")
                            if isinstance(state.get("worker_control"), dict)
                            else ""
                        )
                        != str(spawn_attempt_id)
                    )
                )
            ):
                # A stale child (including Popen-before-Stop-before-new-Resume)
                # exits before touching state or the stop marker.
                return
            if spawn_attempt_id:
                expected_attempt = str(
                    durable_control.get("spawn_attempt_id")
                    if control_generation
                    else state.get("worker_spawn_attempt_id") or ""
                )
                if expected_attempt != spawn_attempt_id:
                    return
                published_pid = worker_pid_value(state.get("pid"))
                if published_pid is not None and published_pid != os.getpid():
                    # A sibling from the same intent can exist only after a
                    # parent crash. The durable per-Popen attempt/PID is the
                    # first-adopter CAS; a non-winning child exits untouched.
                    return
            runtime_epoch = current_runtime_epoch()
            own_identity = worker_pid_identity(
                os.getpid(),
                run_id,
                runtime_epoch=runtime_epoch,
                generation=control_generation,
                launch_id=launch_id,
                spawn_attempt_id=spawn_attempt_id,
            )
            now_text = utcnow()
            if isinstance(own_identity, dict) and (control_generation or spawn_attempt_id):
                own_identity["adopted"] = True
                own_identity["adopted_at"] = now_text
            # Replace the parent's adopted=false handoff record even though it
            # already contains this PID.  The durable bit is what lets a later
            # Stop/Resume distinguish an owned worker from a stale child that
            # has not yet crossed this exact-token check.
            state["pid"] = own_identity
            state["worker_runtime_epoch"] = runtime_epoch
            state["worker_pid_identity_version"] = WORKER_PID_IDENTITY_VERSION
            if spawn_attempt_id:
                state["worker_spawn_attempt_id"] = spawn_attempt_id
            state["_worker_state_writer"] = True
            state["_worker_launch_generation"] = control_generation
            state["_worker_launch_id"] = launch_id
            state["_worker_spawn_attempt_id"] = spawn_attempt_id
            control = state.get("worker_control")
            request = state.get("resume_request")
            if control_generation and isinstance(control, dict):
                control.update(status="running", updated_at=now_text, started_at=now_text)
            if control_generation and isinstance(request, dict):
                request.update(status="running", updated_at=now_text, started_at=now_text)
            # Participant workflows are supervised services.  An older build
            # persisted STOPPED as the active phase, so merely launching a new
            # worker would immediately exit its main loop.  A durable Resume
            # restores the last safe phase before the child advertises itself
            # as running; infer_stopped_resume_phase also handles legacy rows
            # that predate stopped_from_phase.
            if control_generation and str(state.get("phase") or "").upper() == "STOPPED":
                state["phase"] = infer_stopped_resume_phase(state)
                state.pop("stopped_from_phase", None)
            save_state(state)
        stop = run_dir(run_id) / "stop"
        mailer: Mailer | WebChannel | None = None
        stop_consumed_from_phase = ""
        try:
            while True:
                try:
                    migrate_state(state)
                    if reconcile_interrupted_developer_reply(state):
                        save_state(state)
                    if reconcile_completed_experience_feedback(state):
                        save_state(state)
                    if reconcile_interrupted_owner_acceptance(state):
                        save_state(state)
                    active_hold = (
                        state.get("safety_hold")
                        if isinstance(state.get("safety_hold"), dict)
                        else state.get("recovery_required")
                        if isinstance(state.get("recovery_required"), dict)
                        else None
                    )
                    if active_hold is not None:
                        state["internal_recovery_diagnostic"] = dict(active_hold)
                        state.pop("safety_hold", None)
                        state.pop("recovery_required", None)
                        _rotate_phase_sessions_for_recovery(state)
                        clear_worker_recovery(state)
                        state["status"] = live_status(str(state.get("phase") or "DEVELOP"))
                        set_public_work_summary(
                            state,
                            kind="recovering",
                            current="正在核对最新状态，已有进度和消息均已保存",
                            next_step="核对完成后会自动继续，无需手动恢复",
                        )
                        event(
                            state,
                            "workflow_start_auto_recovered_hold",
                            reason_code=str(active_hold.get("reason_code") or "unknown"),
                            recoverable=active_hold.get("recoverable") is True,
                        )
                        save_state(state)
                    retry_after = float(state.get("worker_retry_after") or 0)
                    if retry_after > time.time():
                        state["status"] = "retrying_error"
                        save_state(state)
                        if once:
                            return
                        if wait_for_stop(
                            stop,
                            retry_after - time.time(),
                            run_id=run_id,
                            worker_generation=control_generation,
                        ):
                            if stop_request_is_current(run_id, stop):
                                stop_consumed_from_phase = str(state.get("phase") or "PLAN")
                            return
                    state["status"] = live_status(state["phase"])
                    save_state(state)
                    break
                except Exception as exc:
                    error_text = f"{type(exc).__name__}: {exc}"
                    delay, rotated = prepare_worker_retry(state, error_text)
                    state["status"] = "retrying_error"
                    state["internal_recovery_diagnostic"] = {
                        "reason_code": "state_migration_retry",
                        "recoverable": True,
                        "phase": str(state.get("phase") or "DEVELOP"),
                        "last_error": error_text[:1_000],
                        "created_at": utcnow(),
                    }
                    state.pop("safety_hold", None)
                    state.pop("recovery_required", None)
                    set_public_work_summary(
                        state,
                        kind="retrying",
                        current=(
                            "The latest progress is being synchronized; all work and messages are saved."
                            if prompt_ui_locale(state) == "en"
                            else "正在同步最新进度，已有工作和消息均已保存。"
                        ),
                        next_step=(
                            "Development will continue automatically after synchronization."
                            if prompt_ui_locale(state) == "en"
                            else "同步完成后会自动继续研发，无需手动恢复。"
                        ),
                    )
                    event(
                        state,
                        "migration_retry_scheduled",
                        delay=delay,
                        session_rotated=rotated,
                        error=error_text,
                    )
                    save_state(state)
                    if once:
                        return
                    if wait_for_stop(
                        stop,
                        delay,
                        run_id=run_id,
                        worker_generation=control_generation,
                    ):
                        if stop_request_is_current(run_id, stop):
                            stop_consumed_from_phase = str(state.get("phase") or "PLAN")
                        return
            while state["phase"] != "STOPPED":
                if newer_resume_handoff_pending(run_id, control_generation):
                    # Commit boundaries above have completed. Yield ownership
                    # without doing another workflow step; finalization clears
                    # this PID while preserving the newer accepted intent for
                    # the reconciler to launch exactly once.
                    break
                if stop_request_is_current(run_id, stop):
                    stop_consumed_from_phase = str(state.get("phase") or "PLAN")
                    state["stopped_from_phase"] = state["phase"]
                    state["phase"], state["status"] = "STOPPED", "stopped"
                    set_public_phase_summary(state)
                    break
                try:
                    workflow_step_succeeded = False
                    mailer = mailer or (WebChannel(state) if state.get("channel") == "web" else Mailer(state))
                    ensure_developer_welcome(state, mailer)
                    if state.get("pending_notice"):
                        send_notice(state, mailer)
                    # A direct developer-chat turn may have edited a project
                    # while it was already delivered.  Check before the
                    # DELIVERED idle branch so changed code can never continue
                    # to expose the prior ready-to-publish candidate.
                    if invalidate_delivered_candidate_if_changed(state):
                        save_state(state)
                    pending = state.get("pending_user") or {}
                    if state["phase"] == "WAIT_USER" and pending:
                        send_pending_question(state, mailer)
                    messages: list[dict[str, Any]] = []
                    web_message_serviced = False
                    operations_request_serviced = False
                    operations_refresh_serviced = False
                    if state.get("channel") == "web":
                        web_message_serviced = service_priority_web_messages(
                            state,
                            mailer,
                            boundary="scheduler",
                        )
                    elif time.time() >= float(state.get("imap_retry_after", 0)):
                        try:
                            messages = mailer.poll(state)
                            had_mail_error = "last_mail_error" in state or "imap_retry_after" in state
                            state.pop("last_mail_error", None)
                            state.pop("imap_retry_after", None)
                            if had_mail_error:
                                save_state(state)
                        except (OSError, imaplib.IMAP4.error) as exc:
                            state["last_mail_error"] = f"{type(exc).__name__}: {exc}"
                            state["imap_retry_after"] = time.time() + max(60, int(state["poll_seconds"]))
                            event(state, "imap_retry", error=state["last_mail_error"])
                            save_state(state)
                    if not web_message_serviced and not messages:
                        # Operations chat/deploy turns run between workflow
                        # tasks. Fresh developer messages still keep priority.
                        operations_request_serviced = process_one_operations_request(state)
                        if not operations_request_serviced:
                            # A refresh is one independent read-only turn.
                            operations_refresh_serviced = process_one_operations_refresh(state)
                    if web_message_serviced:
                        # Re-enter the scheduler after every user turn so the
                        # next task is built from the newly updated context.
                        pass
                    elif messages:
                        process_inbound_message(state, mailer, messages[0])
                    elif operations_request_serviced:
                        pass
                    elif operations_refresh_serviced:
                        pass
                    elif process_one_iteration_feedback_cycle(state, mailer):
                        pass
                    elif process_eufr_p0_feedback_cycle(state, mailer):
                        pass
                    elif service_next_owner_acceptance(state):
                        # Source-bound Owner-intent acceptance is an independent
                        # Computer Use turn. It must not wait for persona testing
                        # and may route an observed failure back to development.
                        pass
                    elif replay_due(state):
                        state["phase"], state["status"] = "REPLAY", "running"
                        set_public_phase_summary(state)
                        resume_gate = developer_message_resume_gate(state)
                        workflow_step(state, mailer)
                        workflow_step_succeeded = True
                        if resume_gate is not None:
                            complete_developer_message_resume_gate(
                                state,
                                expected_id=str(resume_gate.get("id") or ""),
                                boundary="workflow_step_complete",
                            )
                    elif state["phase"] in {"WAIT_USER", "DELIVERED"}:
                        state["status"] = live_status(state["phase"])
                        save_state(state)
                        if once:
                            break
                        idle_seconds = max(15, int(state["poll_seconds"]))
                        if state["phase"] == "DELIVERED" and replay_state(state).get("next_at"):
                            idle_seconds = max(1, min(idle_seconds, float(replay_state(state)["next_at"]) - time.time()))
                        wait_for_stop(
                            stop,
                            idle_seconds,
                            run_id=run_id,
                            worker_generation=control_generation,
                        )
                        continue
                    elif state["phase"] == "PLAN" and time.time() < float(state.get("planning_retry_after", 0)):
                        save_state(state)
                        if once:
                            break
                        wait_for_stop(
                            stop,
                            min(int(state["poll_seconds"]), float(state["planning_retry_after"]) - time.time()),
                            run_id=run_id,
                            worker_generation=control_generation,
                        )
                        continue
                    else:
                        # Clear stale retry/error banners as soon as a new turn
                        # starts. Previously this happened only after a successful
                        # step, so long-running Claude calls left the UI stuck on
                        # the previous failure even while status was running.
                        if str(state.get("status") or "") == "retrying_error" or state.get("last_error"):
                            begin_worker_retry_attempt(state)
                            save_state(state)
                        resume_gate = developer_message_resume_gate(state)
                        workflow_step(state, mailer)
                        workflow_step_succeeded = True
                        if resume_gate is not None:
                            complete_developer_message_resume_gate(
                                state,
                                expected_id=str(resume_gate.get("id") or ""),
                                boundary="workflow_step_complete",
                            )
                    if state.get("status") in {"stopped", "recovery_required", "paused_safety"}:
                        save_state(state)
                        break
                    if workflow_step_succeeded:
                        clear_worker_recovery(state)
                    state["status"] = live_status(state["phase"])
                    save_state(state)
                    if once:
                        break
                except WorkflowStopRequested:
                    with contextlib.suppress(Exception):
                        recover_study_preview_checkpoint(state)
                    stop_consumed_from_phase = str(state.get("phase") or "PLAN")
                    state["stopped_from_phase"] = state["phase"]
                    state["phase"], state["status"] = "STOPPED", "stopped"
                    set_public_phase_summary(state)
                    event(state, "stopped", reason="user_request_during_agent_call")
                    save_state(state)
                    break
                except FatalWorkflowError as exc:
                    hold = classify_safety_hold(exc, state)
                    state["internal_recovery_diagnostic"] = hold
                    state.pop("recovery_required", None)
                    state["last_error"] = hold["last_error"]
                    event(
                        state,
                        "safety_hold",
                        error=state["last_error"],
                        reason_code=hold["reason_code"],
                        recoverable=bool(hold.get("recoverable")),
                        resume_action=hold["resume_action"],
                    )
                    if hold.get("recoverable") is True:
                        state.pop("safety_hold", None)
                        _rotate_phase_sessions_for_recovery(state)
                        delay = max(30, min(300, int(state.get("poll_seconds") or 30)))
                        state["worker_retry_after"] = time.time() + delay
                        state["status"] = "retrying_error"
                        set_public_work_summary(
                            state,
                            kind="recovering",
                            current="正在核对最新版本，已有进度和消息均已保存",
                            next_step="系统会自动继续处理，无需手动恢复",
                        )
                        save_state(state)
                        if once:
                            break
                        mailer = None
                        wait_for_stop(
                            stop,
                            delay,
                            run_id=run_id,
                            worker_generation=control_generation,
                        )
                        continue
                    # Unrecoverable integrity failures must not auto-retry.
                    # Retrying here republished the same "round 1 delivered"
                    # bubble every time a read-only tester wrote runtime data.
                    state["safety_hold"] = hold
                    state["status"] = "paused_safety"
                    set_public_work_summary(
                        state,
                        kind="stopped",
                        current="当前版本完整性检查未通过，已停止自动重试以免重复交付",
                        next_step="不会自动复读本轮交付；修复只读越权后再继续内测循环",
                    )
                    save_state(state)
                    break
                except Exception as exc:
                    error_text = f"{type(exc).__name__}: {exc}"
                    recovered_checkpoint = False
                    if str(state.get("phase") or "").upper() == "DEVELOP":
                        with contextlib.suppress(Exception):
                            recovered_checkpoint = (
                                recover_study_preview_checkpoint(state)
                                or usable_development_preview_checkpoint(state)
                            )
                    if (
                        recovered_checkpoint
                        and first_developer_delivery_complete(state)
                        and schedule_developmental_experience(
                            state,
                            mailer,
                            trigger="developer_stall",
                            developer_error=error_text,
                        )
                    ):
                        state["last_transient_error"] = error_text[:1_000]
                        event(
                            state,
                            "developer_stall_routed_to_internal_test",
                            error=error_text[:1_000],
                            candidate_id=str(
                                (state.get("developmental_experience") or {}).get("candidate_id") or ""
                            ),
                        )
                        save_state(state)
                        if once:
                            break
                        mailer = None
                        continue
                    delay, rotated = prepare_worker_retry(state, error_text)
                    if state.get("status") in {"stopped", "recovery_required", "paused_safety"}:
                        event(
                            state,
                            "worker_terminal_failure",
                            status=str(state.get("status") or ""),
                            reason_code=str(state.get("worker_retry_reason_code") or ""),
                        )
                        save_state(state)
                        break
                    en_ui = prompt_ui_locale(state) == "en"
                    if en_ui:
                        retry_current = (
                            "Retrying; switched to a new development session with a condensed handoff"
                            if rotated
                            else "Retrying"
                        )
                        retry_next = f"Will automatically retry in about {delay} seconds"
                    else:
                        retry_current = (
                            "正在重试；已切换到新的研发会话并保留精简交接"
                            if rotated
                            else "正在重试"
                        )
                        retry_next = f"约 {delay} 秒后自动再次尝试"
                    set_public_work_summary(
                        state,
                        kind="retrying",
                        current=retry_current,
                        next_step=retry_next,
                    )
                    event(
                        state,
                        "worker_retry",
                        attempt=state["worker_retry_count"],
                        same_error_count=state["worker_retry_same_error_count"],
                        delay=delay,
                        reason_code=state["worker_retry_reason_code"],
                        session_rotated=rotated,
                        error=state["last_error"],
                    )
                    save_state(state)
                    if once:
                        raise
                    # Retry progress is operational state, not a developer reply.
                    # ``public_state.retry`` drives the live header badge and
                    # countdown; writing the same information to the conversation
                    # ledger made it look as if the developer agent had replied.
                    mailer = None
                    wait_for_stop(
                        stop,
                        delay,
                        run_id=run_id,
                        worker_generation=control_generation,
                    )
        except KeyboardInterrupt:
            state["status"] = "paused"
            event(state, "paused", reason="keyboard_interrupt")
        finally:
            with WorkerLaunchLock(run_id):
                latest = load_state(run_id)
                replacement: tuple[str, int, str] | None = None
                owns_pid = worker_pid_identity_matches(
                    effective_worker_identity(latest),
                    pid=os.getpid(),
                    generation=control_generation,
                    launch_id=launch_id,
                    spawn_attempt_id=spawn_attempt_id,
                )
                if owns_pid:
                    latest["pid"] = None
                control = latest.get("worker_control")
                control = control if isinstance(control, dict) else {}
                control_command = str(control.get("command") or "")
                control_generation_now = int(control.get("generation") or 0)
                now_text = utcnow()
                if stop_consumed_from_phase and control_command == "stop":
                    # The gen-N worker is authorized to commit terminal state for
                    # the validated Stop N+1 while preserving the N+1 control row.
                    latest["stopped_from_phase"] = stop_consumed_from_phase
                    latest["phase"] = "STOPPED"
                    latest["status"] = "stopped"
                    control.update(status="stopped", updated_at=now_text, stopped_at=now_text)
                elif (
                    control_command == "resume"
                    and control_generation_now > control_generation
                    and owns_pid
                ):
                    request = latest.get("resume_request")
                    pending_handoff = bool(
                        isinstance(request, dict)
                        and str(control.get("status") or "") in {"accepted", "launching"}
                        and str(request.get("status") or "") in {"accepted", "launching"}
                        and int(request.get("generation") or 0) == control_generation_now
                        and str(request.get("launch_id") or "")
                        == str(control.get("launch_id") or "")
                        and str(request.get("client_request_id") or "")
                        == str(control.get("client_request_id") or "")
                        and bool(str(control.get("launch_id") or ""))
                        and bool(str(control.get("client_request_id") or ""))
                    )
                    safety_terminal = bool(
                        isinstance(latest.get("safety_hold"), dict)
                        or isinstance(latest.get("recovery_required"), dict)
                        or str(latest.get("status") or "")
                        in {"paused_error", "paused_safety", "recovery_required"}
                    )
                    if pending_handoff and not safety_terminal:
                        # A newer Resume never claims an older PID as running.
                        # At this safe boundary the old owner exits, clears PID,
                        # and preserves one accepted intent for Web/CLI replay.
                        latest["status"] = "resume_requested"
                        control.update(status="accepted", updated_at=now_text)
                        request.update(status="accepted", updated_at=now_text)
                        replacement = (
                            str(control.get("client_request_id") or ""),
                            control_generation_now,
                            str(control.get("launch_id") or ""),
                        )
                    else:
                        if latest.get("phase") == "STOPPED":
                            latest["status"] = "stopped"
                        elif latest.get("status") in {"running", "retrying_error", "starting"}:
                            latest["status"] = "paused"
                        terminal = (
                            "failed" if latest.get("status") == "paused_error" else "paused"
                        )
                        control.update(status=terminal, updated_at=now_text)
                        if isinstance(request, dict):
                            request.update(status=terminal, updated_at=now_text)
                elif owns_pid:
                    if latest.get("phase") == "STOPPED":
                        latest["status"] = "stopped"
                    elif latest.get("status") in {"running", "retrying_error", "starting"}:
                        latest["status"] = "paused"
                    if control_command == "resume":
                        terminal = "failed" if latest.get("status") == "paused_error" else "paused"
                        control.update(status=terminal, updated_at=now_text)
                        request = latest.get("resume_request")
                        if isinstance(request, dict):
                            request.update(status=terminal, updated_at=now_text)
                # Finalization operates on a fresh state loaded while holding
                # the launch lock, so mark its writer baseline as the exact
                # command it just reconciled (including generation zero).
                latest["_worker_state_writer"] = True
                latest["_worker_launch_generation"] = control_generation_now
                latest["_worker_launch_id"] = str(control.get("launch_id") or "")
                latest["_worker_spawn_attempt_id"] = str(
                    control.get("spawn_attempt_id") or ""
                )
                save_state(latest)
                if replacement is not None:
                    # Resume is a durable agent obligation even when no Web
                    # service exists.  The old owner has completed its atomic
                    # step and cleared its PID; while retaining the same
                    # cross-process launch lock, publish exactly one fresh
                    # attempt/PID handoff.  A concurrent Web watcher or CLI
                    # duplicate observes that handoff and deduplicates.
                    replacement_client_id, replacement_generation, replacement_launch_id = (
                        replacement
                    )
                    _spawn_worker_locked(
                        run_id,
                        client_request_id=replacement_client_id,
                        generation=replacement_generation,
                        launch_id=replacement_launch_id,
                    )
                    latest = load_state(run_id)
                if state is not latest:
                    state.clear()
                    state.update(latest)


def new_state(args: argparse.Namespace) -> dict[str, Any]:
    workspace = Path(args.workspace).expanduser().resolve()
    if not workspace.is_dir():
        raise WorkflowError(f"工作空间不存在: {workspace}")
    if not args.intent.strip():
        raise WorkflowError("用户意图不能为空")
    email_address = str(getattr(args, "email", "") or "").strip()
    channel = str(getattr(args, "channel", "") or ("email" if email_address else "web"))
    coding_agent = str(getattr(args, "coding_agent", "claude") or "claude")
    if coding_agent not in {"claude", "codex"}:
        raise WorkflowError(f"不支持的 coding agent: {coding_agent}")
    if channel == "email" and not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email_address):
        raise WorkflowError("邮件通道需要有效的 --email 用户邮箱")
    study_evaluation_protocol = normalize_study_evaluation_protocol(
        getattr(args, "study_evaluation_protocol_json", "")
    )
    study_condition = ""
    initial_files: list[str] = []
    seen_initial_files: set[str] = set()
    raw_initial_files = list(getattr(args, "input_file", None) or [])
    if len(raw_initial_files) > 24:
        raise WorkflowError("创建工作流时最多提供 24 个资料文件")
    for raw_path in raw_initial_files:
        try:
            input_path = Path(str(raw_path or "")).expanduser().resolve(strict=True)
            input_path.relative_to(workspace)
        except (FileNotFoundError, OSError, RuntimeError, ValueError) as exc:
            raise WorkflowError(f"资料文件不存在或不在工作空间内: {raw_path}") from exc
        if not input_path.is_file():
            raise WorkflowError(f"资料路径不是文件: {input_path}")
        normalized = os.path.normcase(str(input_path))
        if normalized in seen_initial_files:
            continue
        seen_initial_files.add(normalized)
        initial_files.append(str(input_path))
    run_id = "wf-" + dt.datetime.now().strftime("%Y%m%d-%H%M%S") + "-" + uuid.uuid4().hex[:8]
    guardrail_file = workspace / ".claude-workflow" / f"guardrails.{run_id}.jsonl"
    state = {
        "version": VERSION,
        "run_id": run_id,
        "created_at": utcnow(),
        "updated_at": utcnow(),
        "pid": None,
        "worker_runtime_epoch": "",
        "worker_pid_identity_version": WORKER_PID_IDENTITY_VERSION,
        "status": "created",
        "phase": "PLAN",
        "round": 0,
        "cycle_started_round": 0,
        "intent": args.intent.strip(),
        "coding_agent": coding_agent,
        "channel": channel,
        "user_email": email_address,
        "workspace": str(workspace),
        "initial_files": initial_files,
        "guardrail_file": str(guardrail_file),
        "guardrail_store": str(run_dir(run_id) / "guardrails.jsonl"),
        "guardrail_revision": 0,
        "initial_guardrails_extracted": False,
        "sessions": {},
        "personas": [],
        "tasks": [],
        "feedback": [],
        "user_messages": [],
        "requirement_semantics": [],
        "developer_message_queue": [],
        "user_attention": {
            "unread": 0,
            "processing": 0,
            "pending": 0,
            "oldest_enqueued_at": "",
            "processing_message_id": "",
        },
        "internal_test_queue": [],
        "development_checkpoints": [],
        "developmental_experience_candidates": [],
        "developmental_experience_history": [],
        "developmental_experience_rounds": 0,
        "experience_mode": "",
        "feedback_clusters": {
            "version": FEEDBACK_CLUSTER_VERSION,
            "candidate_id": "",
            "round": 0,
            "clusters": [],
        },
        "scenario_evidence": {
            "version": SCENARIO_EVIDENCE_VERSION,
            "records": [],
        },
        "internal_test_analysis": None,
        "test_maintainer_contract": None,
        "test_maintainer_proposed": [],
        "test_maintainer_applied": [],
        "test_maintainer_rejected": [],
        "test_maintainer_results": None,
        "test_maintainer_schedule": {"calls": 0, "rounds": []},
        "feedback_patch_receipts": [],
        "pending_feedback_replays": [],
        "pending_owner_feedback": [],
        "owner_intent_profile": {},
        "owner_feedback_prechecks": [],
        "owner_proxy_rounds": {},
        "owner_proxy_receipts": [],
        "owner_proxy_attention_queue": [],
        "owner_acceptance_history": [],
        "owner_proxy_bypass": False,
        "ui_locale": app_i18n.normalize_locale(getattr(args, "ui_locale", "zh-CN")),
        "experience_twin": None,
        "lifecycle": default_product_lifecycle(),
        "runtime_install_authorizations": {},
        "runtime_environment": None,
        "runtime_notice_fingerprints": [],
        "runtime_install_result_notice_fingerprints": [],
        "processed_message_ids": [],
        "mail_thread": {},
        "mail_threads": {},
        "mail_outbox": {},
        "web_threads": {},
        "web_outbox": {},
        "conversation_ledger": {},
        "resolved_pending_ids": [],
        "retired_pending": {},
        "mail_classification_contexts": {},
        "mail_subject_revision": 2,
        "public_mail_revision": 2,
        "confirmation_policy_revision": CONFIRMATION_POLICY_REVISION,
        "guardrail_semantics_revision": GUARDRAIL_SEMANTICS_REVISION,
        "deferred_feedback": {},
        "replay": {"problem_stats": {}, "history": [], "next_at": None, "current": None},
        "pending_user": None,
        "pending_notice": None,
        "mail_config": str(Path(args.mail_config).expanduser().resolve()) if args.mail_config else "",
        "mail_provider": args.mail_provider or "",
        "model": args.model or "",
        "role_model_overrides": {},
        "study_evaluation_protocol": study_evaluation_protocol,
        "study_condition": study_condition,
        "release_evaluator_attempt_semantics_version": RELEASE_EVALUATOR_ATTEMPT_SEMANTICS_VERSION,
        "release_evaluator_attempts": {},
        "release_evaluator_transport_failures": {},
        "candidate_readiness": {
            "schema_version": 2,
            "stage": "developing",
            "candidate_id": "",
            "guardrail_set_id": "",
            "sandbox_ready": False,
            "trial_ready": False,
            "acceptance_ready": False,
            "trial_surface_ids": [],
            "history": [],
        },
        "mcp_config": str(Path(args.mcp_config).expanduser().resolve()) if args.mcp_config else "",
        "coding_agent_cli_args": (
            {"claude": f"--max-budget-usd {args.max_budget_usd}", "codex": ""}
            if getattr(args, "max_budget_usd", None) is not None
            else {"claude": "", "codex": ""}
        ),
        "agent_timeout": args.agent_timeout,
        "poll_seconds": args.poll_seconds,
        "max_rounds": args.max_rounds,
        "strict_round_limit": bool(getattr(args, "strict_round_limit", False)),
        "chrome": args.chrome,
    }
    state["mail_thread"] = {"subject": channel_subject(state, "main"), "legacy_subject_bootstrapped": True}
    if channel == "email":
        Mailer(state)  # validate credentials/config before writing any workflow file
    run_dir(run_id).mkdir(parents=True, exist_ok=False)
    save_state(state)
    # Keep the verbatim intent as immutable provenance, not as an umbrella
    # active guardrail that would make later replace/disable operations conflict.
    append_guardrail(state, "source", "SOURCE-001", text=args.intent.strip(), source="initial:verbatim")
    return state


def _spawn_worker_locked(
    run_id: str,
    once: bool = False,
    *,
    client_request_id: str = "",
    generation: int = 0,
    launch_id: str = "",
) -> int:
    log = run_dir(run_id) / "worker.log"
    state = load_state(run_id)
    if generation and not worker_control_matches(
        state,
        generation=generation,
        launch_id=launch_id,
    ):
        return 0
    control = state.get("worker_control")
    request = state.get("resume_request")
    if generation and (
        not isinstance(request, dict)
        or str(request.get("client_request_id") or "") != str(client_request_id)
        or int(request.get("generation") or 0) != int(generation)
        or str(request.get("launch_id") or "") != str(launch_id)
    ):
        return 0
    current_attempt_id = str(
        (control.get("spawn_attempt_id") or "")
        if generation and isinstance(control, dict)
        else state.get("worker_spawn_attempt_id") or ""
    )
    existing_identity = effective_worker_identity(state)
    existing_pid = worker_pid_value(existing_identity)
    existing_alive = existing_pid is not None and process_alive(existing_identity)
    adopted_live_worker = bool(
        existing_alive and worker_pid_identity_is_adopted(existing_identity, state)
    )
    if generation:
        control_status = str(control.get("status") or "") if isinstance(control, dict) else ""
        request_status = str(request.get("status") or "") if isinstance(request, dict) else ""
        pending = control_status in {"accepted", "launching"} and request_status in {
            "accepted",
            "launching",
        }
        already_running_here = (
            control_status == "running"
            and request_status == "running"
            and adopted_live_worker
        )
        if not pending and not already_running_here:
            return 0
    if existing_alive:
        exact_handoff = worker_pid_identity_matches(
            existing_identity,
            pid=existing_pid,
            generation=generation,
            launch_id=launch_id,
            spawn_attempt_id=current_attempt_id,
        )
        if exact_handoff or adopted_live_worker:
            # A duplicate launcher may observe the exact PID token before the
            # child adopts it. Reuse that handoff, but keep it ``launching``;
            # marking it running would make a later Stop/Resume mistake the
            # still-stale child for an owned worker. A different, already-owned
            # PID is likewise only a handoff candidate: it exits at its next
            # safe boundary and leaves this Resume accepted for replay.
            return existing_pid
    state["status"] = "starting"
    state["pid"] = None
    state["worker_runtime_epoch"] = current_runtime_epoch()
    state["worker_pid_identity_version"] = WORKER_PID_IDENTITY_VERSION
    spawn_attempt_id = uuid.uuid4().hex
    state["worker_spawn_attempt_id"] = spawn_attempt_id
    now_text = utcnow()
    if generation and isinstance(control, dict):
        control.update(
            status="launching",
            updated_at=now_text,
            spawn_attempt_id=spawn_attempt_id,
        )
    if generation and isinstance(request, dict):
        request.update(
            status="launching",
            updated_at=now_text,
            spawn_attempt_id=spawn_attempt_id,
        )
    save_state(state)
    cmd = [sys.executable, str(Path(__file__).resolve()), "_worker", run_id]
    if generation:
        cmd.extend(
            [
                "--control-generation",
                str(generation),
                "--launch-id",
                launch_id,
                "--spawn-attempt-id",
                spawn_attempt_id,
            ]
        )
    else:
        cmd.extend(["--spawn-attempt-id", spawn_attempt_id])
    if client_request_id:
        cmd.extend(["--client-request-id", client_request_id])
    if once:
        cmd.append("--once")
    kwargs: dict[str, Any] = {"stdin": subprocess.DEVNULL, "stderr": subprocess.STDOUT, "close_fds": True}
    if os.name == "nt":
        kwargs["creationflags"] = subprocess.CREATE_NEW_PROCESS_GROUP | subprocess.DETACHED_PROCESS
    else:
        kwargs["start_new_session"] = True
    try:
        with log.open("ab") as out:
            proc = subprocess.Popen(cmd, stdout=out, **kwargs)
    except OSError as exc:
        if generation and (
            isinstance(control, dict)
            and isinstance(request, dict)
            and int(control.get("generation") or 0) == int(generation)
            and str(control.get("launch_id") or "") == str(launch_id)
            and str(control.get("spawn_attempt_id") or "") == spawn_attempt_id
            and int(request.get("generation") or 0) == int(generation)
            and str(request.get("launch_id") or "") == str(launch_id)
            and str(request.get("spawn_attempt_id") or "") == spawn_attempt_id
        ):
            now_text = utcnow()
            control.update(status="failed", updated_at=now_text, failed_at=now_text)
            request.update(status="failed", updated_at=now_text, failed_at=now_text)
            hold = (
                state.get("safety_hold")
                if isinstance(state.get("safety_hold"), dict)
                else state.get("recovery_required")
                if isinstance(state.get("recovery_required"), dict)
                else None
            )
            failure_detail = "workflow worker process could not be started"
            if isinstance(hold, dict):
                state["status"] = (
                    "recovery_required"
                    if hold.get("recoverable") is True
                    else "paused_safety"
                )
                state["resume_launch_error"] = failure_detail
            elif (
                str(state.get("phase") or "").upper() == "DELIVERED"
                or state.get("strict_round_limit_handoff")
            ):
                state["status"] = "delivered_listening"
                state["resume_launch_error"] = failure_detail
            else:
                state["status"] = "paused_error"
                state["last_error"] = failure_detail
            state["pid"] = None
            # The request/control rows retain the attempt nonce as an audit
            # fence, but it no longer owns a prospective worker PID.
            state.pop("worker_spawn_attempt_id", None)
            save_state(state)
        elif not generation:
            state["status"] = "paused_error"
            state["last_error"] = str(exc)
            save_state(state)
        raise WorkflowError(f"无法启动后台 worker: {exc}") from exc
    # The child takes WorkerLaunchLock and validates this exact token before
    # making any state change. Publish PID/identity before releasing the lock.
    state = load_state(run_id)
    if generation and not worker_control_matches(
        state,
        generation=generation,
        launch_id=launch_id,
    ):
        return proc.pid
    control = state.get("worker_control")
    if generation and (
        not isinstance(control, dict)
        or str(control.get("spawn_attempt_id") or "") != spawn_attempt_id
    ):
        return proc.pid
    if not generation and str(state.get("worker_spawn_attempt_id") or "") != spawn_attempt_id:
        return proc.pid
    runtime_epoch = current_runtime_epoch()
    parent_identity = worker_pid_identity(
        proc.pid,
        run_id,
        runtime_epoch=runtime_epoch,
        generation=generation,
        launch_id=launch_id,
        spawn_attempt_id=spawn_attempt_id,
    )
    if isinstance(parent_identity, dict) and spawn_attempt_id:
        parent_identity["adopted"] = False
    state["pid"] = parent_identity
    state["worker_runtime_epoch"] = runtime_epoch
    state["worker_pid_identity_version"] = WORKER_PID_IDENTITY_VERSION
    state["status"] = "starting"
    control = state.get("worker_control")
    request = state.get("resume_request")
    now_text = utcnow()
    if generation and isinstance(control, dict):
        control.update(status="launching", updated_at=now_text, pid=proc.pid)
    if generation and isinstance(request, dict):
        request.update(status="launching", updated_at=now_text, pid=proc.pid)
    save_state(state)
    return proc.pid


def spawn_worker(
    run_id: str,
    once: bool = False,
    *,
    client_request_id: str = "",
    generation: int = 0,
    launch_id: str = "",
) -> int:
    with WorkerLaunchLock(run_id):
        return _spawn_worker_locked(
            run_id,
            once=once,
            client_request_id=client_request_id,
            generation=generation,
            launch_id=launch_id,
        )


def summary(state: dict[str, Any]) -> dict[str, Any]:
    effective_identity = effective_worker_identity(state)
    return {
        "run_id": state["run_id"],
        "coding_agent": state.get("coding_agent", "claude"),
        "channel": state.get("channel", "email"),
        "status": state["status"],
        "phase": state["phase"],
        "round": state["round"],
        "pid": worker_pid_value(effective_identity),
        "pid_alive": process_alive(effective_identity),
        "workspace": state["workspace"],
        "guardrail_file": state["guardrail_file"],
        "active_guardrails": len(active_guardrails(state)),
        "tasks": len(state.get("tasks") or []),
        "personas": len(state.get("personas") or []),
        "pending_question": bool(state.get("pending_user")),
        "pending_question_sent": bool((state.get("pending_user") or {}).get("sent_at")),
        "last_mail_error": state.get("last_mail_error"),
        "updated_at": state["updated_at"],
        "last_error": state.get("last_error"),
        "delivered_candidate": state.get("delivered_candidate"),
    }


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="单文件多会话开发/体验流水线")
    sub = p.add_subparsers(dest="command", required=True)
    start = sub.add_parser("start", help="创建并启动工作流")
    start.add_argument("--intent", required=True, help="例如：开发一个面向老师的排课 Web 应用")
    start.add_argument("--coding-agent", choices=["claude", "codex"], default="claude", help="本地 coding agent CLI")
    start.add_argument("--channel", choices=["web", "email"], default="", help="交互通道；省略时有 --email 则兼容邮件，否则使用 web")
    start.add_argument("--email", default="", help="邮件通道的用户邮箱；web 通道不需要")
    start.add_argument("--workspace", required=True, help="已有或新的代码工作空间")
    start.add_argument(
        "--input-file",
        action="append",
        default=[],
        help="创建应用时提供的资料文件（必须位于 workspace 内，可重复）",
    )
    start.add_argument("--mail-config", default=os.environ.get("WF_MAIL_CONFIG", ""), help="兼容参考项目 email_providers 的 JSON/YAML")
    start.add_argument("--mail-provider", default=os.environ.get("WF_MAIL_PROVIDER", ""))
    start.add_argument("--model", default=os.environ.get("WF_MODEL") or os.environ.get("WF_CLAUDE_MODEL", ""))
    start.add_argument(
        "--ui-locale",
        choices=("zh-CN", "en"),
        default=app_i18n.normalize_locale(os.environ.get("WF_UI_LOCALE", "zh-CN")),
        help="Participant-facing language persisted before the first planning turn.",
    )
    start.add_argument("--mcp-config", default=os.environ.get("WF_MCP_CONFIG", ""))
    start.add_argument(
        "--study-evaluation-protocol-json",
        default="",
        help=argparse.SUPPRESS,
    )
    start.add_argument("--max-budget-usd", type=float, default=None, help="兼容旧参数；建议改用 coding_agent_cli_args 或 Web 高级参数")
    start.add_argument("--agent-timeout", type=int, default=int(os.environ.get("WF_AGENT_TIMEOUT", "3600")))
    start.add_argument("--poll-seconds", type=int, default=int(os.environ.get("WF_POLL_SECONDS", "45")))
    start.add_argument("--max-rounds", type=int, default=int(os.environ.get("WF_MAX_ROUNDS", "20")))
    start.add_argument(
        "--strict-round-limit",
        action="store_true",
        help="Stop at max-rounds and deliver the frozen reviewable candidate instead of auto-extending.",
    )
    start.add_argument("--no-chrome", dest="chrome", action="store_false", help="禁用浏览器 Computer Use；Android/其他已配置工具仍可用")
    start.set_defaults(chrome=True)
    start.add_argument("--detach", action="store_true", help="后台运行并立即返回 workflow ID/PID")
    start.add_argument("--once", action="store_true", help="只执行一个状态步骤，便于调试")
    resume = sub.add_parser("resume", help="按持久化 workflow ID 续跑")
    resume.add_argument("run_id")
    resume.add_argument("--detach", action="store_true")
    resume.add_argument("--once", action="store_true")
    resume.add_argument("--client-request-id", default="", help=argparse.SUPPRESS)
    resume.add_argument("--control-generation", type=int, default=0, help=argparse.SUPPRESS)
    resume.add_argument("--launch-id", default="", help=argparse.SUPPRESS)
    status = sub.add_parser("status", help="查看状态")
    status.add_argument("run_id")
    stop = sub.add_parser("stop", help="在安全边界停止 worker")
    stop.add_argument("run_id")
    sub.add_parser("list", help="列出本机工作流")
    doctor = sub.add_parser("doctor", help="检查本地 coding agent CLI 和邮件配置")
    doctor.add_argument("--mail-config", default=os.environ.get("WF_MAIL_CONFIG", ""))
    doctor.add_argument("--mail-provider", default=os.environ.get("WF_MAIL_PROVIDER", ""))
    worker = sub.add_parser("_worker", help=argparse.SUPPRESS)
    worker.add_argument("run_id")
    worker.add_argument("--once", action="store_true")
    worker.add_argument("--client-request-id", default="", help=argparse.SUPPRESS)
    worker.add_argument("--control-generation", type=int, default=0, help=argparse.SUPPRESS)
    worker.add_argument("--launch-id", default="", help=argparse.SUPPRESS)
    worker.add_argument("--spawn-attempt-id", default="", help=argparse.SUPPRESS)
    return p


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        if args.command == "start":
            if args.once and args.detach:
                raise WorkflowError("--once 与 --detach 不能同时使用")
            state = new_state(args)
            print(json.dumps(summary(state), ensure_ascii=False, indent=2))
            if args.detach:
                print(f"PID={spawn_worker(state['run_id'])}")
            else:
                run_workflow(state["run_id"], once=args.once)
            return 0
        if args.command == "resume":
            resume_state = load_state(args.run_id)
            # A delayed launcher may arrive after the durable resume intent was
            # cancelled or terminally resolved. Reject that stale intent before
            # migration performs any workspace/Git probing; the command is an
            # idempotent no-op and must not revive or otherwise touch the run.
            supplied_generation = int(args.control_generation or 0)
            if supplied_generation:
                supplied_launch_id = str(args.launch_id or "")
                supplied_request_id = str(args.client_request_id or "")
                pending_request = resume_state.get("resume_request")
                pending_request = pending_request if isinstance(pending_request, dict) else {}
                pending_status = str(pending_request.get("status") or "")
                if (
                    not worker_control_matches(
                        resume_state,
                        generation=supplied_generation,
                        launch_id=supplied_launch_id,
                    )
                    or str(pending_request.get("client_request_id") or "") != supplied_request_id
                    or int(pending_request.get("generation") or 0) != supplied_generation
                    or str(pending_request.get("launch_id") or "") != supplied_launch_id
                    or pending_status not in {"accepted", "launching", "running"}
                ):
                    return 0
            migrate_state(resume_state)
            if (
                resume_state.get("strict_round_limit_handoff")
                or str(resume_state.get("phase") or "").upper() == "DELIVERED"
            ):
                raise WorkflowError(
                    "当前流程已进入 release 验收边界，不能恢复自动研发；请在上线页继续验收"
                )
            request_id = str(args.client_request_id or "")
            generation = int(args.control_generation or 0)
            launch_id = str(args.launch_id or "")
            if not generation:
                queued = queue_resume_request(args.run_id, request_id)
                request_id = str(queued.get("client_request_id") or request_id)
                generation = int(queued.get("generation") or 0)
                launch_id = str(queued.get("launch_id") or "")
                if queued.get("pid_alive") and not queued.get("launch_required"):
                    print(
                        f"WORKFLOW_ID={args.run_id}\n"
                        f"PID={worker_pid_value(effective_worker_identity(load_state(args.run_id))) or 0}"
                    )
                    return 0
            try:
                with WorkerLaunchLock(args.run_id):
                    state = load_state(args.run_id)
                    request = state.get("resume_request")
                    request = request if isinstance(request, dict) else {}
                    if (
                        not worker_control_matches(
                            state,
                            generation=generation,
                            launch_id=launch_id,
                        )
                        or str(request.get("client_request_id") or "") != request_id
                        or int(request.get("generation") or 0) != generation
                        or str(request.get("launch_id") or "") != launch_id
                        or (
                            str(request.get("status") or "")
                            not in {"accepted", "launching"}
                            and not (
                                str(request.get("status") or "") == "running"
                                and effective_worker_is_alive(state)
                            )
                        )
                    ):
                        return 0
                    if effective_worker_is_alive(state):
                        pid = _spawn_worker_locked(
                            args.run_id,
                            once=args.once,
                            client_request_id=request_id,
                            generation=generation,
                            launch_id=launch_id,
                        )
                        print(f"WORKFLOW_ID={args.run_id}\nPID={pid}")
                        return 0
                    if str(state.get("status") or "") == "resume_requested":
                        state["status"] = str(request.get("previous_status") or "paused")
                    migrate_state(state)
                    prepare_recovery_resume(state)
                    if state["phase"] == "STOPPED":
                        state["phase"] = infer_stopped_resume_phase(state)
                        state.pop("stopped_from_phase", None)
                        set_public_phase_summary(state)
                    state["status"] = "resume_requested"
                    save_state(state)
                    if args.detach:
                        pid = _spawn_worker_locked(
                            args.run_id,
                            once=args.once,
                            client_request_id=request_id,
                            generation=generation,
                            launch_id=launch_id,
                        )
                    else:
                        pid = 0
                if args.detach:
                    print(f"WORKFLOW_ID={args.run_id}\nPID={pid}")
                else:
                    run_workflow(
                        args.run_id,
                        once=args.once,
                        control_generation=generation,
                        launch_id=launch_id,
                        client_request_id=request_id,
                    )
            except WorkflowError as exc:
                fail_resume_request(
                    args.run_id,
                    request_id,
                    str(exc),
                    generation=generation,
                    launch_id=launch_id,
                )
                raise
            return 0
        if args.command == "status":
            print(json.dumps(summary(load_state(args.run_id)), ensure_ascii=False, indent=2))
            return 0
        if args.command == "stop":
            queue_stop_request(args.run_id)
            print(f"已请求停止 {args.run_id}；当前 coding agent 调用完成后生效。")
            return 0
        if args.command == "list":
            root = state_home() / "runs"
            rows = []
            for path in sorted(root.glob("wf-*/state.json"), reverse=True) if root.exists() else []:
                with contextlib.suppress(Exception):
                    rows.append(summary(load_state(path.parent.name)))
            print(json.dumps(rows, ensure_ascii=False, indent=2))
            return 0
        if args.command == "doctor":
            claude = resolve_cli_executable(os.environ.get("CLAUDE_BIN", ""), "claude")
            codex = resolve_cli_executable(os.environ.get("CODEX_BIN", ""), "codex")
            result: dict[str, Any] = {"claude": claude or "missing", "codex": codex or "missing", "mail": "unchecked"}
            healthy_agents: list[str] = []
            for name, executable in (("claude", claude), ("codex", codex)):
                if not executable:
                    continue
                try:
                    proc = subprocess.run(
                        [*cli_command_prefix(executable), "--version"],
                        capture_output=True,
                        text=True,
                        encoding="utf-8",
                        errors="replace",
                        timeout=20,
                        check=False,
                        **hidden_process_kwargs(),
                    )
                    version = (proc.stdout or proc.stderr).strip()
                    if proc.returncode == 0:
                        result[f"{name}_version"] = version
                        healthy_agents.append(name)
                    else:
                        result[f"{name}_error"] = f"exit {proc.returncode}: {version}".strip()
                except (OSError, subprocess.TimeoutExpired) as exc:
                    result[f"{name}_error"] = f"{type(exc).__name__}: {exc}"
            fake = {"mail_config": args.mail_config, "mail_provider": args.mail_provider}
            try:
                mailer = Mailer(fake)
                result["mail"] = {"smtp": f"{mailer.smtp_host}:{mailer.smtp_port}/{mailer.security}", "imap": f"{mailer.imap_host}:{mailer.imap_port}", "sender": mailer.sender}
            except Exception as exc:
                result["mail"] = f"error: {exc}"
            print(json.dumps(result, ensure_ascii=False, indent=2))
            return 0 if healthy_agents and isinstance(result["mail"], dict) else 1
        if args.command == "_worker":
            run_workflow(
                args.run_id,
                once=args.once,
                control_generation=args.control_generation,
                launch_id=args.launch_id,
                client_request_id=args.client_request_id,
                spawn_attempt_id=args.spawn_attempt_id,
            )
            return 0
    except WorkflowError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
